// Calendar dates are evaluated in Japan, regardless of the device's time zone.
function japanDate(now=new Date()) {
  const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);
  const get=k=>parts.find(p=>p.type===k).value;
  return `${get('year')}-${get('month')}-${get('day')}`;
}
function dateNumber(value) {
  if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))return null;
  const [y,m,d]=value.split('-').map(Number);
  if(y<1900||y>2199)return null;
  const n=Date.UTC(y,m-1,d),dt=new Date(n);
  return dt.getUTCFullYear()===y&&dt.getUTCMonth()===m-1&&dt.getUTCDate()===d?n/86400000:null;
}
function daysUntil(date,today=japanDate()){const a=dateNumber(date),b=dateNumber(today);return a===null||b===null?null:a-b;}
function calendarAfter(date,days){return new Date((dateNumber(date)+days)*86400000).toISOString().slice(0,10);}
function upgradeState(saved) {
  const result={...defaults(),...saved};
  if(saved&&saved.contentVersion!==3){
    // Preserve the old course rather than crediting changed questions as answered.
    result.previousArchives=[...(saved.previousArchives||[]),...(saved.legacy?[saved.legacy]:[])];
    result.legacy={contentVersion:saved.contentVersion||1,trophies:saved.trophies||{},passes:saved.passes||{},completed:saved.completed||[],answers:saved.answers||{},first:saved.first||{},tasks:saved.tasks||{},tests:saved.tests||[],notes:{...saved.notes},archivedAt:new Date().toISOString()};
    result.completed=[];result.answers={};result.first={};result.tasks={};result.tests=[];result.passes={};result.reviewRequired={};result.trophies=Object.fromEntries(Object.entries(saved.trophies||{}).filter(([k])=>!k.startsWith('unit')));
    result.notes=Object.fromEntries(Object.entries(saved.notes||{}).map(([k,v])=>[k.startsWith('day-')?k:'旧版-'+k,v]));
  }
  result.contentVersion=3;result.voiceRates||=[1,.96];result.audioLead||=500;
  result.notebook||={};result.trophies||={};result.passes||={};result.examDate||='';
  return result;
}
function assessmentPass(result){return result.total===12&&result.score>=10&&['listen','both','read'].every(k=>result.cats[k]?.total===4&&result.cats[k]?.ok>=2);}
function reviewSchedule(entry,today=japanDate()){
  if(!entry?.writtenAt)return [];
  return [1,3,7].map(offset=>({offset,date:calendarAfter(entry.writtenAt,offset),done:!!entry.recalled?.[offset]})).map(x=>({...x,due:!x.done&&dateNumber(x.date)<=dateNumber(today)}));
}

'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const KEY='bjt-school-pilot-1:'+boot.storageNamespace+':'+boot.studentId;
const defaults=()=>({version:1,contentVersion:3,garden:{selected:1,reviews:{},reducedMotion:false},examDate:'',notebook:{},voices:['',''],voiceRates:[1,.96],audioLead:500,trophies:{},passes:{},reviewRequired:{},recovered:false,completed:[],answers:{},first:{},tasks:{},known:[],notes:{},tests:[],ruby:true});
let state=defaults(),storageOK=true,activeQuiz=null,wordFilter='all',wordSearch='',bankFilter='all',timer=null;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&saved.version===1&&Array.isArray(saved.completed)&&typeof saved.answers==='object'&&saved.answers&&Array.isArray(saved.known)){state=upgradeState(saved);}localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const glossary=Object.fromEntries(LESSONS.flatMap(l=>l.words.map(w=>[w[0],w[1]])));
Object.assign(glossary,{'聴解':'ちょうかい','聴読解':'ちょうどっかい','読解':'どっかい','敬語':'けいご','取引先':'とりひきさき','資料':'しりょう','会議':'かいぎ','修正':'しゅうせい','納品':'のうひん','印刷':'いんさつ','経理':'けいり','総務':'そうむ','了承':'りょうしょう','配付':'はいふ','入荷':'にゅうか','発送':'はっそう','返事':'へんじ','上司':'じょうし','部下':'ぶか','予定':'よてい','研修':'けんしゅう','筆記用具':'ひっきようぐ','継続使用':'けいぞくしよう'});
const rubyRE=new RegExp(Object.keys(glossary).sort((a,b)=>b.length-a.length).map(s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'g');
const txt=s=>esc(s).replace(rubyRE,m=>`<ruby>${m}<rt>${glossary[m]}</rt></ruby>`);
const icon=name=>{const paths={garden:'<path d="M12 16V9m0 4C5 13 4 8 5 5c5 0 7 3 7 6m0-1c1-5 5-6 8-5 0 5-3 8-8 8M6 17h12l-2 5H8z"/>',home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',plan:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18M7 14h2m6 0h2M7 17h2"/>',practice:'<path d="m9 4 11 8-11 8z"/>',words:'<path d="M12 5C7 2 3 4 3 4v15s4-2 9 1c5-3 9-1 9-1V4s-4-2-9 1v15"/>',review:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8m-8 4h8m-8 4h5"/>',guide:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',sound:'<path d="M3 9h4l5-4v14l-5-4H3zm13-1c3 2 3 6 0 8m3-11c5 4 5 10 0 14"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>'};return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.plan}</svg>`;};
const CATS={listen:'聴解',both:'聴読解',read:'読解'};
const WEEK=[{n:'01',name:'職場の基本を知る',sub:'あいさつ・敬語・指示',from:1,to:7},{n:'02',name:'相手の意図をつかむ',sub:'依頼・電話・会議',from:8,to:14},{n:'03',name:'情報を整理して判断',sub:'納期・表・複数の条件',from:15,to:21},{n:'04',name:'ビジネス場面を攻略',sub:'総合演習・弱点の復習',from:22,to:28}];
const dailyTasks=[['words','今日の3語をノートに書き、見ずに思い出す'],['listen','聞く → 答える → 文字で確認 → まねして話す'],['read','読む → 答える → 根拠と他の選択肢を比較'],['output','例文を自分の場面に変えて話す'],['review','間違えた理由を書く → 解き直す']];
const getQ=id=>QUESTIONS.find(q=>q.id===id)||ASSESSMENTS.find(q=>q.id===id);
const nextDay=()=>LESSONS.findIndex((_,i)=>!state.completed.includes(i+1))+1||30;
const wrongIds=()=>Object.keys(state.answers).filter(id=>getQ(id)&&!state.answers[id].correct);
const attempted=()=>QUESTIONS.filter(q=>state.answers[q.id]).length;
function save(){unlockTrophies();try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}storageNotice();}
function storageNotice(){const e=$('#storage-warning');e.classList.toggle('hide',storageOK);if(!storageOK)e.textContent='このブラウザーでは学習記録を保存できません。現在の画面では学習できますが、閉じると記録が失われる場合があります。';}
let toastID;function toast(message){$('#toast').textContent=message;clearTimeout(toastID);toastID=setTimeout(()=>$('#toast').textContent='',3500);}
function nav(){const path=location.hash.slice(1).split('/')[0]||'home';const selected=path==='lesson'?'plan':path==='quiz'?'practice':path==='question'?(getQ(location.hash.split('/')[1])?.unit?'practice':'plan'):path;const links=[['home','ホーム'],['plan','練習問題'],['practice','テスト'],['words','自作単語帳'],['review','復習ノート'],['study','学習・解説'],['garden','わたしの庭'],['guide','勉強の進め方']];$('#nav').innerHTML=links.map(([key,label])=>`<a href="#${key}" class="${selected===key?'active':''}" ${selected===key?'aria-current="page"':''}>${icon(key)}${label}${key==='review'&&wrongIds().length?`<span class="nav-badge">${wrongIds().length}</span>`:''}</a>`).join('');$('#breadcrumb').textContent=links.find(x=>x[0]===selected)?.[1]||'ホーム';$('#side-progress').innerHTML=`<div class="progress"><span style="width:${state.completed.length/30*100}%"></span></div><p>${state.completed.length} / 30 レッスン完了</p>`;}
function footer(){return `<footer class="site-footer"><span>BJT STEP 30 · 自主学習用オリジナル教材／非公式<br>単語音声：<a href="https://voicevox.hiroshiba.jp/product/namine_ritsu/" target="_blank" rel="noopener noreferrer">VOICEVOX:波音リツ</a></span><span>記録はこのブラウザーに保存 <span aria-hidden="true">·</span> <a href="#guide">教材について</a></span></footer>`;}
function intro(eyebrow,title,sub=''){return `<div class="page-intro"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div></div>`;}
function art(){return `<div class="hero-art"><img src="${SCENE_ASSETS['hero-study']}" alt="机でノートに書く学習者と小さな鉢植え" width="1024" height="1024"></div>`;}
function home(){const day=nextDay(),l=LESSONS[day-1],n=state.completed.length;return intro('YOUR JAPANESE, ONE STEP FORWARD','こんにちは。今日も、一歩ずつ。','N3の日本語を、仕事で使える力へ。')+`<section class="hero"><div class="hero-copy"><div class="tag"><span class="dot"></span>30 DAYS / J2 CHALLENGE</div><h2>今日の一歩が、<br>仕事の日本語になる。</h2><p>聞いて、読んで、相手の意図をつかむ。<br>30日間の練習で、BJTのJ2を目指しましょう。</p><div class="actions"><a href="#lesson/${day}" class="btn blue">${n===30?'レッスンを復習':'今日の学習を始める'} ${icon('arrow')}</a><button class="btn text" data-action="start-test" data-mode="diagnostic">はじめのチェック ↗</button></div><p class="hero-foot">JLPT N3程度から · 目標 J2：420〜529点</p></div>${art()}</section><div class="stats"><div class="stat"><div><div class="label">学習の進み具合</div><strong>${n}</strong><span class="unit">/ 30 日</span><div class="detail">${n===0?'今日からスタートしましょう':n===30?'全レッスンを完了しました':'自分のペースで続けよう'}</div></div><div class="stat-icon">${icon('plan')}</div></div><div class="stat"><div><div class="label">見ずに思い出せた</div><strong>${state.known.length}</strong><span class="unit">/ 90 語</span><div class="detail">仕事で使う表現を少しずつ</div></div><div class="stat-icon">${icon('words')}</div></div><div class="stat"><div><div class="label">もう一度、練習</div><strong>${wrongIds().length}</strong><span class="unit">問</span><div class="detail">${wrongIds().length?'復習ノートで確認しよう':'解答後に苦手を見つけよう'}</div></div><div class="stat-icon">${icon('review')}</div></div></div><div class="content-grid"><section><div class="section-heading"><h2>今日のレッスン</h2><a href="#plan">練習問題を見る ↗</a></div><div class="today-card"><div class="lesson-top"><span class="pill">DAY ${String(day).padStart(2,'0')} · ${day>28?'FINAL':'UNIT '+(WEEK.findIndex(w=>day>=w.from&&day<=w.to)+1)}</span><span class="small muted">内容を理解して進もう</span></div><h3>${l.title}</h3><p>${l.goal}</p><div class="actions" style="margin-top:14px"><span class="pill blue">${day%2?'聴解':'聴読解'}</span><span class="pill muted">読解</span><span class="pill muted">ことば 3語</span></div><div class="lesson-footer"><span>解説 → 練習 → 振り返り</span><a class="btn soft" href="#lesson/${day}">学習する ${icon('arrow')}</a></div></div><div class="week-mini">${WEEK.map((w,i)=>`<a href="#plan" class="${day>=w.from&&day<=w.to?'current':''}"><small>WEEK ${w.n}</small><b>${['基本を知る','意図をつかむ','情報を整理','実践と仕上げ'][i]}</b><span>${state.completed.filter(d=>d>=w.from&&d<=w.to).length}/${w.to-w.from+1} 日 完了</span></a>`).join('')}</div><div class="notice">まずは「はじめのチェック」で練習する分野を見つけましょう。1か月でのJ2到達には個人差があります。正答率はBJTの点数ではありません。</div></section><aside><div class="section-heading"><h2>今日すること</h2></div><div class="panel" style="padding:8px 21px">${dailyTasks.map((t,i)=>`<div class="time-row"><span class="num">0${i+1}</span><div>${t[1]}</div></div>`).join('')}</div><div class="tip"><b>学びのヒント</b>全部のことばが分からなくても大丈夫。「だれが・何を・いつまでに」をつかむ練習から始めましょう。</div></aside></div>`+journey()+officialLinks()+legacyHTML();}
function plan(){return intro('PRACTICE BY UNIT','練習問題','状況をつかみ、根拠を見つけ、自分の言葉で説明しよう。')+`<div class="notice">敬語や文書の読み方に迷ったら、<a href="#study">「学習・解説」</a>で確認できます。各単元の練習が終わったら、<a href="#practice">テストにチャレンジ →</a></div>`+[1,2,3,4,5].map(n=>`<section class="week-block"><div class="section-heading"><h2>${n===5?'最後の2日':'単元 '+n+' · '+WEEK[n-1].name}</h2><a href="#practice">達成状況・テストへ ↗</a></div><div class="day-grid">${unitDays(n).map(d=>{const l=LESSONS[d-1];return `<a class="day-card ${state.completed.includes(d)?'done':''}" href="#lesson/${d}"><div class="lesson-top"><span class="pill">DAY ${String(d).padStart(2,'0')}</span><small>${state.completed.includes(d)?'✓ 完了':'未完了'}</small></div><h3>${esc(l.title)}</h3><p>${esc(l.goal)}</p><span class="bottom">${d%2?'聴解':'聴読解'} ＋ 読解 · ノート3語 ↗</span></a>`;}).join('')}</div></section>`).join('')+exerciseBank();}
function lesson(day){if(!Number.isInteger(day)||day<1||day>30)return empty('レッスンが見つかりません','プランから学習する日を選んでください。','#plan','プランを見る');const l=LESSONS[day-1],qs=QUESTIONS.filter(q=>q.day===day),tasks=state.tasks[day]||{};return `<a href="#plan" class="back">← 練習問題</a>`+intro(`DAY ${String(day).padStart(2,'0')} / 30`,l.title,txt(l.goal))+`<div class="lesson-layout"><div class="lesson-body"><section class="panel"><span class="pill">01 · ポイントを知る</span><h2 style="margin-top:15px">場面と意味をつなげよう</h2><p>${txt(l.point)}</p><p class="phrase">${txt(l.phrase)}</p><button class="btn text" data-action="speak-phrase" data-day="${day}">${icon('sound')} 例文を聞く</button><span class="small muted" id="phrase-status" role="status"></span></section><section class="panel"><span class="pill">02 · 今日のことば</span><div class="vocab-mini" style="margin-top:17px">${l.words.map(w=>`<div><b>${txt(w[0])}</b><p>${txt(w[2])}</p></div>`).join('')}</div><a href="#words/${day}" class="btn text">自分のノートに書く・復習 ↗</a></section><section><h2>03 · 練習してみよう</h2><p class="wide-note">オリジナルの学習問題です。音声は最初に文字を見ずに聞き、答えた後でスクリプトと解説を確認しましょう。</p>${qs.map(q=>questionHTML(q,'daily')).join('')}</section><section class="panel"><span class="pill">04 · 自分の言葉で</span><h2 style="margin-top:15px">声に出して、使ってみよう</h2><p>${txt(l.task)}</p>${[7,14,21,27].includes(day)?'<a class="btn soft" href="#review" style="margin-top:15px">復習ノートを開く</a>':''}${[7,14,21,28,30].includes(day)?'<a class="btn blue" href="#practice" style="margin-top:15px">単元のテストへ</a>':''}${day===29?'<a class="btn soft" href="https://www.kanken.or.jp/bjt/about/level_sample.html" target="_blank" rel="noopener noreferrer" style="margin-top:15px">公式サンプル・CBT体験へ ↗</a>':''}<label for="lesson-note-${day}" class="small muted" style="display:block;margin-top:16px">今日使えるようになった表現・明日復習すること（自動保存）</label><textarea id="lesson-note-${day}" data-note="day-${day}" placeholder="例：締め切りを確認する言い方が分かった。">${esc(state.notes['day-'+day]||'')}</textarea></section></div><aside class="lesson-aside panel"><h3>今日のチェックリスト</h3><p class="small muted" style="margin-top:5px">実際に取り組んだ項目にチェック</p><div class="checklist">${dailyTasks.map(([key,label,mins])=>`<label class="check-row"><input type="checkbox" data-task="${key}" data-day="${day}" ${tasks[key]?'checked':''}><span>${label}</span></label>`).join('')}</div><div class="notice" style="font-size:11px;margin:12px 0">例文は3回音読し、音声を聞いた後にまねして話します。読解は他の選択肢が違う理由も説明しましょう。公式サンプルも活用できます。</div><p class="small muted" id="lesson-completion-info">${completionInfo(day)}</p><button class="btn full ${state.completed.includes(day)?'soft':'blue'}" data-action="complete-day" data-day="${day}" ${canComplete(day)?'':'disabled'} style="margin-top:12px">${state.completed.includes(day)?'✓ この日は学習済み':'今日の学習を完了'}</button><a class="btn text full" href="#lesson/${day===30?1:day+1}" style="margin-top:5px">${day===30?'Day 1に戻る':'次のレッスンへ'} →</a></aside></div>`;}
function canComplete(day){return LESSONS[day-1].words.every((w,j)=>state.notebook[`w${day}-${j}`])&&QUESTIONS.filter(q=>q.day===day).every(q=>state.answers[q.id])&&dailyTasks.every(t=>state.tasks[day]?.[t[0]]);}
function completionInfo(day){const count=QUESTIONS.filter(q=>q.day===day&&state.answers[q.id]).length;return `ノート ${LESSONS[day-1].words.filter((w,j)=>state.notebook[`w${day}-${j}`]).length}/3語 · 練習 ${count}/2問 解答済み · 5項目のチェックで完了できます。` ;}
function optionOrder(q){return [0,1,2,3];}
function empty(title,sub,href,label){return `<div class="empty">${icon('check')}<h2>${title}</h2><p>${sub}</p><a href="${href}" class="btn soft">${label}</a></div>`;}
function review(){const ids=wrongIds();return intro('REFLECT & TRY AGAIN','復習ノート','答えだけでなく、間違えた理由を残しましょう。記録は自動で保存されます。')+`<div class="notice">語彙・数字・敬語・相手の意図・条件の見落とし。どこで迷ったかを言葉にして、もう一度解いてみましょう。</div><div class="section-heading"><h2>もう一度解く <span class="small muted">${ids.length}問</span></h2><a href="#plan">練習問題へ ↗</a></div>${ids.length?ids.map(id=>{const q=getQ(id);return `<article class="review-item"><div class="lesson-top"><span class="pill blue">${CATS[q.type]} · DAY ${q.day}</span><a href="#lesson/${q.day}" class="small">解説を学び直す ↗</a></div>${q.scenario?`<section class="phase4-scenario"><h4>設問の状況</h4><p>${txt(q.scenario)}</p></section>`:""}<h3>${txt(q.prompt)}</h3><p>選んだ答え：${txt(q.options[state.answers[id].choice]||'未回答')}</p><label class="small muted" for="note-${id}">迷った理由・次に気を付けること</label><textarea id="note-${id}" data-note="${id}" placeholder="例：「まで」と「までに」を間違えた。">${esc(state.notes[id]||'')}</textarea><button class="btn soft" style="margin-top:12px" data-action="review-retry" data-q="${id}">この問題を解き直す ${icon('arrow')}</button></article>`;}).join(''):empty('今は、要復習の問題はありません',attempted()?'この調子で、新しい問題にも挑戦しましょう。':'問題を解くと、間違えた問題がここに集まります。','#practice','テストへ')}<section class="section-space"><h2 style="font-size:18px;margin-bottom:13px">学習メモ</h2>${Object.entries(state.notes).filter(([,v])=>v.trim()).length?Object.entries(state.notes).filter(([,v])=>v.trim()).map(([k,v])=>`<details class="review-item"><summary style="cursor:pointer;font-size:13px">${k.startsWith('day-')?'DAY '+k.slice(4)+' の振り返り':`問題 ${esc(k)} のメモ`}</summary><label class="small muted" for="saved-${k}">メモを編集（自動保存）</label><textarea id="saved-${k}" data-note="${esc(k)}">${esc(v)}</textarea></details>`).join(''):'<p class="small muted">レッスンや復習問題で書いたメモをここで確認できます。</p>'}</section><section class="section-space"><h2 style="font-size:18px;margin-bottom:13px">チェックの記録</h2>${state.tests.length?state.tests.slice().reverse().slice(0,8).map(t=>`<div class="review-item"><div class="lesson-top"><b style="font-size:13px">${testTitle(t.mode)}</b><span class="small muted">${new Date(t.date).toLocaleDateString('ja-JP')}</span></div><p>${t.score} / ${t.total} 問 正解（${Math.round(t.score/t.total*100)}%） · ${Object.entries(t.cats).map(([k,v])=>`${CATS[k]} ${v.ok}/${v.total}`).join(' · ')}</p><p>練習問題の正答率です。BJTのスコア・レベルは示しません。</p></div>`).join(''):'<p class="small muted">チェックを最後まで解くと結果が残ります。</p>'}</section>`;}
function guide(){return intro('HOW TO LEARN','勉強の進め方','目標と学び方を知って、自分に合ったペースで続けましょう。')+`<div class="guide-grid"><section class="panel"><span class="pill">目指すレベル</span><h2 style="margin-top:13px">J2は420〜529点</h2><p>J2では、身近な職場の会話や文書を理解し、その場に合うやり取りをする力が求められます。530点からはJ1です。BJTは合格・不合格ではなく、0〜800点のスコアで評価されます。</p><p style="margin-top:13px">JLPT N3とBJTのレベルは直接対応しません。N3程度からの1か月は挑戦的な目標です。開始時の力、学習時間、聴解経験によって到達度は変わります。</p><a class="small" href="https://www.kanken.or.jp/bjt/about/level_sample.html" target="_blank" rel="noopener noreferrer">根拠：BJT公式 レベル＆サンプル ↗</a></section><section class="panel"><span class="pill blue">本試験を知る</span><h2 style="margin-top:13px">3つの力を、バランスよく</h2><div class="table-wrap"><table><thead><tr><th>分野</th><th>問題数</th><th>時間</th></tr></thead><tbody><tr><td>${txt('聴解')}</td><td>25問</td><td>約45分</td></tr><tr><td>${txt('聴読解')}</td><td>25問</td><td>約30分</td></tr><tr><td>${txt('読解')}</td><td>30問</td><td>30分</td></tr></tbody></table></div><p>合計80問・四肢択一。問題を解く時間は約105分、説明などを含め約2時間です。聴解と聴読解は音声に従って進み、前の問題に戻れません。</p><a class="small" href="https://www.kanken.or.jp/bjt/data/bjt_overview_2023webinar.pdf" target="_blank" rel="noopener noreferrer">根拠：BJT公式 試験構成資料 ↗</a> · <a class="small" href="https://www.kanken.or.jp/bjt/contact/" target="_blank" rel="noopener noreferrer">公式FAQ ↗</a></section><section class="panel"><h2>練習のあとに、テストにチャレンジ！</h2><p>「テスト」はレッスンの途中でも、学習前でも受けられます。練習のあとに挑戦し、理解を確かめる使い方もおすすめです。問題を解いた後は、聞き直し・音読・自分の言葉での説明に取り組みます。</p><ol style="padding-left:22px;font-size:13px;line-height:2.3"><li>今日の3語と、前日・3日前・1週間前の語を復習。</li><li>音声を文字なしで聞く→答える→文字で確認→3回まねして話す。</li><li>読解の根拠を探す→4つの選択肢を比較。公式サンプルも活用。</li><li>「自分の言葉で」の課題に取り組み、例文を自分の場面に変える。</li><li>誤答の原因を書く→解き直す→翌日の復習を決める。</li></ol><p>Week 1はゆっくり、Week 2からふつうの音声速度へ。最後の週は最初に1回だけ聞く練習を増やしましょう。</p></section><section class="panel"><h2>結果に合わせた学び方</h2><p>以下は当サイト内の学習方針の目安で、J2到達の基準ではありません。</p><ul><li>正答率50%未満：Day 1〜7の語彙と場面理解を繰り返す。日数を延ばしても構いません。</li><li>50〜79%：解説の根拠を確認し、苦手分野の解説を読み、根拠を確認して解き直す。</li><li>80%以上：再回答の記憶だけで解いていないか確認。未見の公式教材で音声・時間配分に慣れる。</li></ul><p>はじめのチェックと総合練習は学習問題を再利用します。単元テストと最後の確認テストは別問題です。再挑戦では同じ問題を使うため、答えだけでなく根拠を説明しましょう。初めての教材でも理解できるか、先生や学習仲間と確認しましょう。</p></section><section class="panel"><h2>公式の音声・形式にも触れよう</h2><p>このサイトは基礎から実用場面へつなぐ補助教材です。実際の音声、写真、設問の進み方は公式のサンプルやCBT体験で確認してください。</p><div class="guide-links"><a href="https://www.kanken.or.jp/bjt/about/level_sample.html" target="_blank" rel="noopener noreferrer">公式サンプル・CBT体験 <span>↗</span></a><a href="https://www.kanken.or.jp/bjt/" target="_blank" rel="noopener noreferrer">BJT公式サイト・教材案内 <span>↗</span></a><a href="https://www.kanken.or.jp/bjt/contact/" target="_blank" rel="noopener noreferrer">公式FAQ・受験時の確認 <span>↗</span></a></div><p style="margin-top:16px">Day 29では受験案内を開き、本人確認書類・集合時刻・会場を自分で確認しましょう。</p></section><section class="panel"><h2>この教材と学習記録について</h2><p>30レッスン・文書解説6種類・コミュニケーション解説6テーマ・練習60問（聴解15、聴読解15、読解30）・単元と最終テスト60問・90語を収録。すべて独自に作成した非公式教材で、本試験の問題や公式の認定教材ではありません。</p><p style="margin-top:12px">本試験は統計的にスコアを算出するため、当サイトの正答率をBJTの点数に換算できません。J2到達を保証・判定するものではありません。</p><p style="margin-top:12px">単語90語はVOICEVOX:波音リツ（ノーマル・話速0.8）の音声です。単語帳の「聞く」から再生できます。例文・聴解・聴読解はブラウザーの合成音声です。<a href="#voice-settings">声を選ぶ・試す</a>ことができます。端末に日本語音声がない場合は、スクリプトで学習できます。合成音声は本試験の録音音声と異なります。ふりがなは重要語のみ表示します。</p><p style="margin-top:12px">学校版では回答・解説確認・完了・テスト結果を学校の管理表へ送信します。メモ・単語帳・音声設定・庭の表示設定は端末内に保存します。未送信の記録はこの端末に残ります。旧サイトの進捗は「記録の引き継ぎ」で取り込めます。</p><div class="actions"><button class="btn light" data-action="export">学習記録を保存（JSON）</button></div><div class="reset-area"><button class="btn text" data-action="reset-prompt">このブラウザーの学習記録をリセット</button><div id="reset-confirm"></div></div></section></div><p class="small muted" style="margin-top:20px">試験情報の確認日：2026年11月7日。<a href="https://www.kanken.or.jp/bjt/about/feature.html" target="_blank" rel="noopener noreferrer">採点方法の公式説明 ↗</a>　BJTは公益財団法人 日本漢字能力検定協会の登録商標です。</p>`;}
function buildTest(mode){if(mode.startsWith('unit'))return ASSESSMENTS.filter(q=>q.unit===Number(mode.slice(4))).map(q=>q.id);const daySet=mode==='diagnostic'?[1,3,5,2,4,6]:[9,11,15,17,23,25,8,12,16,18,24,28];const qs=[];for(const type of ['listen','both','read']){const selected=QUESTIONS.filter(q=>q.type===type&&(type==='read'?(mode==='diagnostic'?[2,3,6]:[9,14,16,21,24,30]).includes(q.day):daySet.includes(q.day)));qs.push(...selected);}return qs.map(q=>q.id);}
function startTest(mode){if(!['diagnostic','mixed','unit1','unit2','unit3','unit4','unit5'].includes(mode))return;if(activeQuiz&&!activeQuiz.finished){location.hash='quiz';toast('進行中のチェックを再開しました。新しく始める場合は「終了する」を選んでください。');return;}activeQuiz={mode,ids:buildTest(mode),answers:{},index:0,finished:false,started:Date.now(),deadline:mode==='mixed'?Date.now()+18*60*1000:null};location.hash='quiz';if(location.hash==='#quiz')render();}
function quiz(){if(!activeQuiz)return empty('チェックを始めましょう','はじめのチェック、または総合チェックを選んでください。','#practice','テストへ');if(activeQuiz.finished)return resultHTML();const q=getQ(activeQuiz.ids[activeQuiz.index]);return `<div class="quiz-shell"><div class="quiz-header"><div><span class="eyebrow">${activeQuiz.mode==='diagnostic'?'START CHECK':'MIXED PRACTICE'}</span><h1>${testTitle(activeQuiz.mode)}</h1></div>${activeQuiz.deadline?'<span class="clock" id="quiz-clock" aria-label="残り時間">18:00</span>':'<span class="pill">時間制限なし</span>'}</div><p class="small muted">${activeQuiz.index+1} / ${activeQuiz.ids.length}問 · 終了後に解説します。${activeQuiz.mode.startsWith('unit')?'単元テストでは文字を見ずに聞きます。スクリプトは終了後に表示します。':'スクリプト・再生は学習用に利用できます。'}</p><div class="progress" style="margin:15px 0 20px"><span style="width:${(activeQuiz.index+1)/activeQuiz.ids.length*100}%"></span></div>${questionHTML(q,'quiz')}<div class="quiz-nav"><button class="btn light" data-action="quiz-prev" ${activeQuiz.index===0?'disabled':''}>← 前の問題</button><button class="btn text" data-action="quiz-end-prompt">途中で終了する</button><button class="btn blue" data-action="quiz-next" ${activeQuiz.answers[q.id]===undefined?'disabled':''}>${activeQuiz.index===activeQuiz.ids.length-1?'結果を見る':'次の問題 →'}</button></div><div id="quiz-end-confirm"></div><p class="small muted" style="margin-top:18px">練習用チェックです。本試験とは問題数・難易度・制限時間・操作が異なります。途中の状態はこのページを閉じると失われます。</p></div>`;}
function record(q,choice){if(!schoolRecordingTest && choice>=0)schoolQueue({type:"answer",questionId:q.id,choice});const a={choice,correct:choice===q.answer,date:new Date().toISOString()};if(a.correct&&state.answers[q.id]&&!state.answers[q.id].correct){state.recovered=true;gardenReview();}state.answers[q.id]=a;if(!state.first[q.id])state.first[q.id]=a;if(a.correct)for(const mode of Object.keys(state.reviewRequired))state.reviewRequired[mode]=state.reviewRequired[mode].filter(id=>id!==q.id);}
function finishTest(expired=false){if(schoolBlocked)return;if(activeQuiz&&!activeQuiz.finished){activeQuiz.schoolEventId=schoolQueue({type:"test_submit",mode:activeQuiz.mode,answers:Object.fromEntries(activeQuiz.ids.map(id=>[id,activeQuiz.answers[id]??null]))});schoolRecordingTest=true;}if(!activeQuiz||activeQuiz.finished)return;stopAudio();let score=0;const cats={listen:{ok:0,total:0},both:{ok:0,total:0},read:{ok:0,total:0}};for(const id of activeQuiz.ids){const q=getQ(id),choice=activeQuiz.answers[id];cats[q.type].total++;if(choice===q.answer){score++;cats[q.type].ok++;}record(q,choice===undefined?-1:choice);}schoolRecordingTest=false;activeQuiz.finished=true;activeQuiz.expired=expired;activeQuiz.result={mode:activeQuiz.mode,score,total:activeQuiz.ids.length,cats,date:new Date().toISOString()};if(activeQuiz.mode.startsWith('unit')){activeQuiz.result.passed=assessmentPass(activeQuiz.result);if(activeQuiz.result.passed){state.passes[activeQuiz.mode]=new Date().toISOString();state.reviewRequired[activeQuiz.mode]=[];}else state.reviewRequired[activeQuiz.mode]=activeQuiz.ids.filter(id=>activeQuiz.answers[id]!==getQ(id).answer);}activeQuiz.result.eventId=activeQuiz.schoolEventId;state.tests.push(activeQuiz.result);state.tests=state.tests.slice(-30);save();render();}
function resultHTML(){const r=activeQuiz.result,pct=Math.round(r.score/r.total*100),low=Object.entries(r.cats).sort((a,b)=>a[1].ok/a[1].total-b[1].ok/b[1].total)[0][0];return `<div class="quiz-shell">${intro('YOUR NEXT STEP','チェック、お疲れさまでした。','結果を使って、次に練習することを決めましょう。')}<section class="panel">${r.mode.startsWith('unit')?`<div class="notice ${r.passed?'':'warn'}"><b>${r.passed?(state.trophies[r.mode]?'テスト達成！ 単元のトロフィーも獲得済みです。':'テスト達成！ レッスンも終えるとトロフィーに近づきます。'):'あと一歩。間違いを復習して再挑戦しよう。'}</b><br>条件：12問中10問以上 ＋ 聴解・聴読解・読解それぞれ4問中2問以上。${r.passed?'':'いつでも再挑戦できます。解説を確認してから取り組むと効果的です。'}</div>`:''}<div class="score-block"><div class="score">${r.score}<span> / ${r.total}</span></div><p>正答率 ${pct}%</p><p class="small muted">${activeQuiz.expired?'時間になりました。未回答は不正解として集計しています。':'未回答は不正解として集計します。'}</p></div><div class="result-grid">${Object.entries(r.cats).map(([k,c])=>`<div class="result-cell">${CATS[k]}<strong>${c.ok} / ${c.total}</strong><div class="progress"><span style="width:${c.ok/c.total*100}%"></span></div></div>`).join('')}</div><div class="notice">${pct<50?'まずはDay 1〜7を中心に、言葉と場面を結び付けて復習しましょう。':pct<80?`${CATS[low]}の問題から、間違えた理由を確認しましょう。根拠を声に出して説明する練習がおすすめです。`:'根拠を説明できるか確認し、未見の公式サンプルや教材にも取り組みましょう。'}<br><b>これは練習の正答率です。BJTスコアやJ2到達の判定ではありません。</b></div><div class="actions"><a class="btn blue" href="#review">間違いを復習</a><a class="btn light" href="#plan">学習プランへ</a><button class="btn text" data-action="new-test">もう一度チェック</button></div></section><h2 style="margin:25px 0 15px;font-size:18px">解答と解説</h2>${activeQuiz.ids.map(id=>{const q=getQ(id),choice=activeQuiz.answers[id];return `<article class="review-item"><span class="pill ${choice===q.answer?'':'amber'}">${choice===q.answer?'✓ 正解':'要復習'} · ${CATS[q.type]}</span>${q.scenario?`<section class="phase4-scenario"><h4>設問の状況</h4><p>${txt(q.scenario)}</p></section>`:""}<h3>${txt(q.prompt)}</h3><p>あなたの答え：${choice===undefined?'未回答':txt(q.options[choice])}</p><p>正解：${txt(q.options[q.answer])}</p><div class="feedback">${explanationHTML(q)}</div><details class="result-source"><summary>本文・音声・スクリプトを確認</summary>${sourceHTML(q)}${audioHTML(q)}</details><a class="btn text" href="#question/${id}">この問題を復習 ↗</a></article>`;}).join('')}</div>`;}
function tick(){updateCountdown();if(!activeQuiz||activeQuiz.finished||!activeQuiz.deadline)return;const remain=Math.max(0,Math.ceil((activeQuiz.deadline-Date.now())/1000));const e=$('#quiz-clock');if(e)e.textContent=`${String(Math.floor(remain/60)).padStart(2,'0')}:${String(remain%60).padStart(2,'0')}`;if(remain===0)finishTest(true);}
let utterance=null,audioStatusEl=null;
if('speechSynthesis'in window){speechSynthesis.getVoices();speechSynthesis.addEventListener('voiceschanged',()=>speechSynthesis.getVoices());}
function updateLessonCompletion(day){const e=$('#lesson-completion-info');if(e)e.textContent=completionInfo(day);const b=$('[data-action="complete-day"]');if(b)b.disabled=!canComplete(day);}
function render(focus=false){stopAudio();nav();document.body.classList.toggle('no-ruby',!state.ruby);$('#ruby-toggle').checked=state.ruby;const [route='home',id]=location.hash.replace(/^#/,'').split('/');const r=route||'home';if(r!=='words')notebookRoute=null;let html;if(r==='home')html=home();else if(r==='plan')html=plan();else if(r==='lesson')html=lesson(Number(id));else if(r==='practice')html=practice();else if(r==='notebook')html=notebook(Number(id));else if(r==='voice-settings')html=voiceSettings();else if(r==='words'){if(notebookRoute!==location.hash){if(id&&Number(id)>=1&&Number(id)<=30){notebookDay=Number(id);wordOriginDay=Number(id);wordSearch='';wordFilter='all';}else wordOriginDay=notebookDay||nextDay();notebookRoute=location.hash;}html=words();}else if(r==='review')html=review();else if(r==='study')html=study(id);else if(r==='garden')html=garden();else if(r==='guide')html=guide();else if(r==='quiz')html=quiz();else if(r==='question'){const q=getQ(id);html=q?`<a href="${q.unit?'#practice':'#plan'}" class="back">← ${q.unit?'テスト':'練習問題'}</a><div class="quiz-shell">${intro(q.unit?'TEST REVIEW':`DAY ${q.day}`,q.unit?testTitle('unit'+q.unit):LESSONS[q.day-1].title)}${questionHTML(q)}<a class="btn light" href="#lesson/${q.day}">この日のレッスンで学ぶ</a></div>`:empty('問題が見つかりません','練習問題一覧から選んでください。','#plan','練習問題へ');}else html=home();$('#main').innerHTML=html+footer();document.body.classList.toggle('print-notebook',r==='notebook');storageNotice();if(focus){window.scrollTo(0,0);$('.main-shell')?.scrollTo?.(0,0);$('#main').focus({preventScroll:true});}tick();refreshGarden();}
window.addEventListener
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action,day=Number(b.dataset.day),id=b.dataset.q;
if(action==='answer'){const q=getQ(id),choice=Number(b.dataset.choice);if(b.dataset.mode==='quiz'){activeQuiz.answers[id]=choice;const node=$('#question-'+id);node.outerHTML=questionHTML(q,'quiz');const next=$('[data-action="quiz-next"]');if(next)next.disabled=false;}else{record(q,choice);save();stopAudio();$('#question-'+id).outerHTML=questionHTML(q);nav();updateLessonCompletion(q.day);}}
else if(action==='retry'){stopAudio();const q=getQ(id);$('#question-'+id).outerHTML=questionHTML({...q},'retry');}
else if(action==='review-retry'){location.hash='question/'+id;render();const node=$('#question-'+id);if(node)node.outerHTML=questionHTML(getQ(id),'retry');}
else if(action==='complete-day'){if(canComplete(day)&&!state.completed.includes(day)){schoolQueue({type:"lesson_complete",day});state.completed.push(day);save();waterGarden(Math.min(5,Math.ceil(day/7)),`Day ${day}を完了。鉢植えに水をあげました！`);save();nav();b.textContent='✓ この日は学習済み';b.className='btn full soft';}}
else if(action==='play')speak(getQ(id).audio,Number($(`[data-speed="${id}"]`)?.value||1),$('#audio-'+id));
else if(action==='stop')stopAudio();
else if(action==='speak-phrase')speak(LESSONS[day-1].phrase,1,$('#phrase-status'));
else if(action==='word-speak')playWordAudio(b.dataset.word,b);
else if(action==='word-known'){const id=b.dataset.word;state.known=state.known.includes(id)?state.known.filter(x=>x!==id):[...state.known,id];save();const y=window.scrollY;render();window.scrollTo(0,y);}
else if(action==='word-filter'){wordFilter=b.dataset.filter;render();$('#word-search')?.focus();}
else if(action==='bank-filter'){bankFilter=b.dataset.filter;const y=window.scrollY;render();window.scrollTo(0,y);}
else if(action==='start-test')startTest(b.dataset.mode);
else if(action==='quiz-prev'){activeQuiz.index=Math.max(0,activeQuiz.index-1);render(true);}
else if(action==='quiz-next'){if(activeQuiz.index===activeQuiz.ids.length-1)finishTest();else{activeQuiz.index++;render(true);}}
else if(action==='quiz-end-prompt')$('#quiz-end-confirm').innerHTML='<div class="notice warn">未回答は不正解として集計します。終了しますか？<div class="actions"><button class="btn light" data-action="quiz-end-cancel">続ける</button><button class="btn soft" data-action="quiz-end">終了して結果を見る</button></div></div>';
else if(action==='quiz-end-cancel')$('#quiz-end-confirm').innerHTML='';
else if(action==='quiz-end')finishTest();
else if(action==='new-test'){const mode=activeQuiz.mode;activeQuiz=null;startTest(mode);}
else if(action==='export'){const blob=new Blob([JSON.stringify({app:'BJT STEP 30',exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='bjt-step30-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('学習記録を保存しました。学校版の記録引き継ぎで取り込めます。');}
else if(action==='reset-prompt')$('#reset-confirm').innerHTML='<div class="notice warn">学習日・解答・ことば・メモ・チェック結果をすべて削除します。元に戻せません。<div class="actions"><button class="btn light" data-action="reset-cancel">キャンセル</button><button class="btn danger" data-action="reset">すべての記録を削除</button></div></div>';
else if(action==='reset-cancel')$('#reset-confirm').innerHTML='';
else if(action==='reset'){const examDate=state.examDate;state=defaults();state.examDate=examDate;activeQuiz=null;save();render();toast('学習記録をリセットしました。');}
});
document.addEventListener('input',e=>{if(e.target.matches('[data-note]')){state.notes[e.target.dataset.note]=e.target.value;save();}if(e.target.id==='word-search'){wordSearch=e.target.value;if(wordSearch.trim()){notebookDay=0;$('#notebook-day').value='0';}$('#word-results').innerHTML=wordResults();}});
document.addEventListener('change',e=>{if(e.target.id==='ruby-toggle'){state.ruby=e.target.checked;document.body.classList.toggle('no-ruby',!state.ruby);save();}if(e.target.matches('[data-task]')){const d=e.target.dataset.day;state.tasks[d]||={};state.tasks[d][e.target.dataset.task]=e.target.checked;save();updateLessonCompletion(Number(d));}});
window.addEventListener('hashchange',()=>render(true));window.addEventListener('pagehide',stopAudio);document.addEventListener('visibilitychange',tick);
timer=setInterval(tick,1000);


const TROPHY_NAMES=['仕事の日本語、第一歩','相手の意図をキャッチ','情報整理の達人','ビジネス場面を攻略','30日チャレンジ達成'];
let shownTranscripts=new Set(),notebookDay=nextDay(),wordOriginDay=nextDay(),notebookRoute=null,voiceRun=0,voicePause=null;
const testTitle=mode=>mode==='diagnostic'?'はじめのチェック':mode==='mixed'?'総合練習':mode==='unit5'?'最後の確認テスト':`単元 ${mode.slice(4)} テスト`;
const unitDays=n=>Array.from({length:n===5?2:7},(_,i)=>(n===5?29:(n-1)*7+1)+i);
const unitReady=n=>unitDays(n).every(d=>state.completed.includes(d))&&(n!==5||[1,2,3,4].every(i=>state.trophies['unit'+i]));
function unlockTrophies(){
  const newNames=[];
  for(let n=1;n<=5;n++)if(unitReady(n)&&state.passes['unit'+n]&&!state.trophies['unit'+n]){state.trophies['unit'+n]=new Date().toISOString();newNames.push(TROPHY_NAMES[n-1]);}
  for(const [id,name,ready] of [['notebook','自分の単語帳、はじめの1語',Object.keys(state.notebook).length>0],['recovery','間違いを力に変えた',state.recovered]])if(ready&&!state.trophies[id]){state.trophies[id]=new Date().toISOString();newNames.push(name);}
  if(newNames.length){const el=$('#achievement');if(el){el.innerHTML=`<span class="award-icon">🏆</span><div><small>実績解除</small><b>${newNames.map(esc).join('<br>')}</b></div><button data-action="dismiss-award" aria-label="実績のお知らせを閉じる">×</button>`;el.hidden=false;}}
}
function trophyHTML(n){const got=state.trophies['unit'+n];return `<div class="trophy ${got?'unlocked':'locked'}"><span aria-hidden="true">${n===5?'💎':'🏆'}</span><small>${n===5?'FINAL':'UNIT 0'+n}</small><b>${TROPHY_NAMES[n-1]}</b><p>${got?'獲得 '+new Date(got).toLocaleDateString('ja-JP',{timeZone:'Asia/Tokyo'}):'レッスン完了 ＋ テスト達成'}</p></div>`;}
function unitCard(n){const days=unitDays(n),done=days.filter(d=>state.completed.includes(d)).length,mode='unit'+n,waiting=state.reviewRequired[mode]||[],passed=state.passes[mode];return `<article class="unit-card ${state.trophies[mode]?'achieved':''}"><div class="lesson-top"><span class="pill">${n===5?'FINAL':'UNIT 0'+n} · DAY ${days[0]}–${days.at(-1)}</span><span aria-hidden="true">${state.trophies[mode]?'🏆':'◇'}</span></div><h3>${n===5?'試験へ、最後の2日':WEEK[n-1].name}</h3><div class="unit-status"><span class="${done===days.length?'passed':''}">学習 ${done} / ${days.length} 完了</span><span class="${passed?'passed':''}">テスト ${passed?'✓ 達成':'未達成'}</span></div><div class="progress"><span style="width:${done/days.length*100}%"></span></div><p class="small">${state.trophies[mode]?'トロフィー獲得！ 庭に花が咲きました。':passed?'テスト達成は保存済み。残りの学習を進めましょう。':'学習前でも、途中でも、自由に受けられます。'}${n===5&&!state.trophies[mode]?' 最後のトロフィーには単元1〜4のトロフィーも必要です。':''}</p><div class="actions"><a class="btn light" href="#lesson/${days.find(d=>!state.completed.includes(d))||days[0]}">${done===days.length?'レッスンを復習':'学習を進める'}</a><button class="btn ${passed?'soft':'blue'}" data-action="start-test" data-mode="${mode}">${passed?'もう一度テスト':'12問テスト'}</button></div>${waiting.length?`<details class="targeted-review"><summary>復習のおすすめ：${waiting.length}問（再受験の制限はありません）</summary>${waiting.map(id=>`<a href="#question/${id}">${CATS[getQ(id).type]}：${esc(getQ(id).prompt)}</a>`).join('')}</details>`:''}</article>`;}
function notebookReturn(){const d=wordOriginDay,n=LESSONS[d-1].words.filter((w,j)=>state.notebook[`w${d}-${j}`]).length;return n?`<div class="notebook-return" role="status"><div><b>DAY ${String(d).padStart(2,'0')}</b><p>${n===3?'3語を書きました。次は問題に挑戦！':`${n} / 3語をノートに書きました。`}</p></div><a class="btn blue" href="#lesson/${d}">練習問題に戻る →</a></div>`:'';}

function journey(){return `<section class="section-space"><div class="section-heading"><h2>次のトロフィーへ</h2><a href="#plan">単元を見る ↗</a></div><div class="trophy-grid">${[1,2,3,4,5].map(trophyHTML).join('')}</div><p class="small muted">テストは12問中10問以上、かつ各分野4問中2問以上で達成。学習の実績であり、BJTレベルの認定ではありません。</p><div class="mini-achievements"><span class="${state.trophies.notebook?'earned':''}">✎ 自分の単語帳、はじめの1語</span><span class="${state.trophies.recovery?'earned':''}">↻ 間違いを力に変えた</span></div>${unitCard([1,2,3,4,5].find(n=>!state.trophies['unit'+n])||5)}</section>`;}
function officialLinks(){return `<section class="official-panel section-space"><div><span class="eyebrow">OFFICIAL BJT</span><h2>公式の音声・問題も試そう</h2><p>このサイトで練習したら、公式サンプルで形式を確認しましょう。</p></div><div class="official-links"><a href="https://www.kanken.or.jp/bjt/" target="_blank" rel="noopener noreferrer">BJT公式サイト ↗</a>${['聴解','聴読解','読解'].map((name,i)=>`<a href="https://www.kanken.or.jp/bjt/sample/sample0${i+1}.html" target="_blank" rel="noopener noreferrer">公式サンプル：${name} ↗</a>`).join('')}</div></section>`;}
function legacyHTML(){return state.legacy?`<details class="notice"><summary>改訂前の学習記録を保存しています</summary><p>旧版で完了したレッスン：${state.legacy.completed.length}日。問題を改稿したため、新版の解答・達成条件は別に記録します。ことばの記憶チェックと学習メモは引き継いでいます。</p><p>${state.legacy.completed.map(d=>'DAY '+d).join(' ／ ')||'完了日は未登録'} ／ 旧版の解答 ${Object.keys(state.legacy.answers).length}問</p><button class="btn light" data-action="export">旧版も含めて記録を保存</button></details>`:'';}
function updateCountdown(){const el=$('#countdown');if(!el)return;const n=daysUntil(state.examDate);el.textContent=n===null?'試験日を設定':n===0?'本日が試験日':n<0?'試験日を過ぎました':`試験まで あと${n}日`;el.title=state.examDate?`試験日：${state.examDate}（日本時間）／クリックして変更`:'試験日を入力できます';}
function examEditor(){const box=$('#exam-editor');box.hidden=false;box.innerHTML=`<div class="panel"><h2>試験日を設定</h2><p class="small muted">日本時間の日付でカウントします。このブラウザーに保存します。</p><label for="exam-date">自分の試験日</label><input id="exam-date" type="date" min="1900-01-01" max="2199-12-31" value="${esc(state.examDate)}"><p id="exam-error" role="alert"></p><div class="actions"><button class="btn blue" data-action="exam-save">保存</button><button class="btn light" data-action="exam-delete">試験日を削除</button><button class="btn text" data-action="exam-close">閉じる</button></div></div>`;$('#exam-date').focus();}
function transcriptHTML(audio){return audio.split(/\n+/).filter(Boolean).map(line=>{const m=line.match(/^([^：:]{1,14})[：:](.*)$/);return m?`<div class="script-line"><b>${esc(m[1])}</b><p>${txt(m[2])}</p></div>`:`<p class="script-narration">${txt(line)}</p>`;}).join('');}
function audioHTML(q,mode='daily'){
  if(!q.audio)return '';
  const test=mode==='quiz'&&activeQuiz?.mode.startsWith('unit');
  const show=shownTranscripts.has(q.id)&&!test;
  return `<div class="audio-box"><div class="audio-controls"><button class="btn light" data-action="play" data-q="${q.id}">${icon('sound')} 音声を聞く</button><button class="btn text" data-action="stop">停止</button><label>速さ <select data-speed="${q.id}" aria-label="音声の速さ"><option value="0.85">ゆっくり</option><option value="1" selected>ふつう</option><option value="1.1">速め</option></select></label>${test?'<span class="small">会話の文字は結果画面で確認できます</span>':`<button class="btn script-button" data-action="transcript" data-q="${q.id}" aria-expanded="${show}" aria-controls="script-${q.id}">${show?'会話の文字を閉じる':'会話の文字を見る'}</button>`}</div><div class="audio-status" id="audio-${q.id}" role="status">端末の日本語音声で再生します。<a href="#voice-settings">声を選ぶ</a></div>${!test?`<div id="script-${q.id}" class="script-panel" ${show?'':'hidden'}><h4>スクリプト</h4>${transcriptHTML(q.audio)}</div>`:''}</div>`;
}
function explanationHTML(q){return `<div class="explain">${txt(q.explain)}</div>${q.why?`<details class="choice-reasons"><summary>4つの選択肢の理由を比べる</summary>${optionOrder(q).map((idx,i)=>`<p><b>${q.audioChoices?i+1:'ABCD'[i]} ${txt(q.options[idx])}</b><br>${txt(q.why[idx])}</p>`).join('')}</details>`:''}`;}
function questionHTML(q,mode='daily'){
  const a=mode==='quiz'||mode==='retry'?null:state.answers[q.id],selected=mode==='quiz'?activeQuiz?.answers[q.id]:a?.choice;
  return `<article class="question" id="question-${q.id}"><div class="lesson-top"><span class="pill ${q.type==='read'?'':'blue'}">${CATS[q.type]} · ${q.unit?'確認テスト':'DAY '+String(q.day).padStart(2,'0')}</span><span class="small muted">${esc(q.section||'オリジナル問題')}</span></div>${sceneSVG(q)}${sourceHTML(q)}${audioHTML(q,mode)}${q.documentType?`<a class="document-help" href="#study/${q.documentType}">この文書の読み方を確認 ↗</a>`:''}${q.scenario?`<section class="phase4-scenario"><h4>設問の状況</h4><p>${txt(q.scenario)}</p></section>`:""}<h3>${txt(q.prompt)}</h3><div class="choices">${optionOrder(q).map((idx,i)=>`<button class="choice ${a?(idx===q.answer?'correct':idx===selected?'wrong':''):idx===selected?'selected':''}" data-action="answer" data-q="${q.id}" data-choice="${idx}" data-mode="${mode}" ${a?'disabled':''} ${!a?`aria-pressed="${idx===selected}"`:''}><span class="letter">${q.audioChoices?i+1:'ABCD'[i]}</span><span>${q.audioChoices&&!a&&(mode==='quiz'||!shownTranscripts.has(q.id))?'選択肢 '+(idx+1):txt(q.options[idx])}${a&&idx===q.answer?' <b>✓ 正解</b>':a&&idx===selected?' <b>× 選んだ答え</b>':''}</span></button>`).join('')}</div>${a?`<div class="feedback ${a.correct?'':'bad'}" role="status"><strong>${a.correct?'✓ 正解です':'もう一度、ポイントを確認しましょう'}</strong>${explanationHTML(q)}</div><div class="actions"><button class="btn text" data-action="retry" data-q="${q.id}">もう一度解く ↻</button><a class="btn text" href="${q.unit?'#practice':'#review'}">${q.unit?'テストへ戻る':'復習ノートへ'} ↗</a></div>`:''}</article>`;
}
function japaneseVoices(){return 'speechSynthesis'in window?speechSynthesis.getVoices().filter(v=>/^ja(?:[-_]|$)/i.test(v.lang)).sort((a,b)=>Number(/Natural|Online|Google/i.test(b.name))-Number(/Natural|Online|Google/i.test(a.name))):[];}
function voiceSelectors(voices=japaneseVoices()){return voices.length?`<div class="voice-selectors">${[0,1].map(i=>`<label>話者 ${i+1}<select data-voice="${i}"><option value="">自動で選ぶ</option>${voices.map(v=>`<option value="${esc(v.voiceURI)}" ${state.voices[i]===v.voiceURI?'selected':''}>${esc(v.name)}</option>`).join('')}</select></label>`).join('')}</div>`:'<p class="notice">利用可能な日本語音声を読み込んでいます。表示されない場合は、端末の音声設定で日本語音声を追加してください。</p>';}
if('speechSynthesis'in window)speechSynthesis.addEventListener('voiceschanged',()=>{const el=$('#voice-list');if(el)el.innerHTML=voiceSelectors();});
function writtenCount(){return Object.keys(state.notebook).length;}
function allWords(){return LESSONS.flatMap((l,i)=>l.words.map((w,j)=>({w,id:`w${i+1}-${j}`,day:i+1})));}
function words(){return intro('MY WORD NOTEBOOK','自分でつくる単語帳','1日3語。自分のノートに書いて、使う場面と一緒に覚えよう。単語音声：VOICEVOX:波音リツ（ノーマル・話速0.8）。')+`<div class="notebook-intro panel"><div><h2>書く → 思い出す → 使ってみる</h2><p>ノートを開き、下の型で1語ずつ書きます。例文は自分の学校・アルバイト・仕事の場面で作りましょう。</p><ol><li>ことば・読み方</li><li>短い意味（母語でもOK）</li><li>使う場面・相手</li><li>自分で作った例文</li><li>直した点と復習日</li></ol><p class="small muted">書いた例文は先生や学習仲間と確認しましょう。サイトでは手書きの内容を自動採点しません。</p><div class="actions"><a class="btn light" href="#notebook/${notebookDay||nextDay()}">書き込み用の用紙を見る・印刷</a></div></div><div class="notebook-preview"><small>わたしのことばノート</small><b>確認（かくにん）</b><p>意味：間違いがないか確かめる</p><p>場面：アルバイトで店長に</p><p>自分の文：明日の集合時間を<br>確認してもよろしいですか。</p><span>翌日 □　3日後 □　7日後 □</span></div></div><div class="stats"><div class="stat"><div><div class="label">ノートに書いた</div><strong>${writtenCount()}</strong><span class="unit">/ 90語</span></div></div><div class="stat"><div><div class="label">見ずに思い出せた</div><strong>${state.known.length}</strong><span class="unit">/ 90語</span></div></div><div class="stat"><div><div class="label">今日までの復習</div><strong>${allWords().filter(x=>reviewSchedule(state.notebook[x.id]).some(r=>r.due)).length}</strong><span class="unit">語</span></div></div></div><div class="toolbar"><label class="search"><span class="small muted">ことば・読み方・意味を検索</span><input id="word-search" type="search" value="${esc(wordSearch)}" placeholder="例：確認、かくにん"></label><label>学習日 <select id="notebook-day"><option value="0">すべて</option>${LESSONS.map((l,i)=>`<option value="${i+1}" ${notebookDay===i+1?'selected':''}>DAY ${i+1}</option>`).join('')}</select></label>${['all','due','unwritten','known'].map(k=>`<button class="chip ${wordFilter===k?'active':''}" data-action="word-filter" data-filter="${k}">${{all:'すべて',due:'今日の復習',unwritten:'まだ書いていない',known:'思い出せた'}[k]}</button>`).join('')}</div><div id="notebook-return">${notebookReturn()}</div><div id="word-results">${wordResults()}</div>`;}
function wordResults(){const ws=allWords().filter(x=>(!notebookDay||x.day===notebookDay)&&x.w.join(' ').includes(wordSearch.trim())&&(wordFilter==='all'||wordFilter==='known'&&state.known.includes(x.id)||wordFilter==='unwritten'&&!state.notebook[x.id]||wordFilter==='due'&&reviewSchedule(state.notebook[x.id]).some(r=>r.due)));return `<p class="small muted" role="status">${ws.length}語を表示</p><div class="word-grid">${ws.map(({w,id,day})=>{const entry=state.notebook[id],schedule=reviewSchedule(entry),due=schedule.find(r=>r.due),recalledToday=Object.values(entry?.recalled||{}).includes(japanDate());return `<article class="word-card ${state.known.includes(id)?'known':''}"><div class="lesson-top"><span class="pill muted">DAY ${String(day).padStart(2,'0')}</span><a class="small" href="#notebook/${day}">用紙 ↗</a></div><h3>${esc(w[0])}</h3><span class="reading">${esc(w[1])}</span><details><summary>意味と場面を確認</summary><p>${txt(w[2])}</p><p>場面：${esc(LESSONS[day-1].title)}</p></details><label class="check-row"><input type="checkbox" data-written="${id}" ${entry?'checked':''}>自分のノートに書いた</label>${entry?`<a class="btn soft full" href="#lesson/${wordOriginDay}" style="margin-top:10px">練習問題に戻る →</a>`:''}<div class="actions"><button class="btn text" data-action="word-speak" data-word="${id}" aria-pressed="false" aria-describedby="word-audio-${id}">${icon('sound')} 聞く</button><button class="btn ${state.known.includes(id)?'soft':'light'}" data-action="word-known" data-word="${id}" aria-pressed="${state.known.includes(id)}">${state.known.includes(id)?'✓ 思い出せた':'見ずに言えた'}</button></div><p id="word-audio-${id}" class="small muted" role="status" aria-live="polite"></p>${entry?`<div class="recall-schedule"><small>書いた日：${entry.writtenAt}</small>${schedule.map(r=>`<span class="${r.done?'done':r.due?'due':''}">${r.done?'✓':'□'} ${r.offset}日後 ${r.date.slice(5)}${r.done?' 済み':r.due?' 復習しよう':''}</span>`).join('')}${due&&!recalledToday?`<button class="btn soft full" data-action="recall" data-word="${id}" data-offset="${due.offset}">ノートを隠して思い出せた</button><p class="small muted">言えなかったら意味を確認し、また挑戦。</p>`:recalledToday?'<p class="small muted">今日の復習を記録しました。</p>':''}</div>`:'<p class="small muted">書いた日から1日・3日・7日後に復習を案内します。</p>'}</article>`;}).join('')}</div>${ws.length?'':empty('この条件のことばはありません','検索や学習日の条件を変えてみましょう。','#words','単語帳へ')}`;}
function notebook(day){if(!Number.isInteger(day)||day<1||day>30)day=nextDay();return intro('WRITE YOUR OWN','DAY '+String(day).padStart(2,'0')+' · 書き込み用単語帳','印刷して使うか、この型を自分のノートに写してください。')+`<div class="actions print-controls"><a class="btn light" href="#words">単語帳に戻る</a><button class="btn blue" data-action="print-notebook">この用紙を印刷</button><label>学習日 <select id="print-day">${LESSONS.map((l,i)=>`<option value="${i+1}" ${day===i+1?'selected':''}>DAY ${i+1} ${esc(l.title)}</option>`).join('')}</select></label></div><div class="print-sheet"><p>名前：________________　学習した日：____年___月___日</p>${LESSONS[day-1].words.map(w=>`<section class="writing-card"><h2>${esc(w[0])} <small>（${esc(w[1])}）</small></h2><div>短い意味：<span class="writing-line"></span></div><div>使う場面・相手：<span class="writing-line"></span></div><div>自分の例文：<span class="writing-line"></span><span class="writing-line"></span></div><div>確認して直した点：<span class="writing-line"></span></div><p>見ずに思い出す：翌日 □　3日後 □　7日後 □</p></section>`).join('')}</div>`;}
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action;
  if(action==='exam-open')examEditor();
  else if(action==='exam-save'){const v=$('#exam-date').value;if(dateNumber(v)===null){$('#exam-error').textContent='正しい試験日を入力してください。';return;}state.examDate=v;save();$('#exam-editor').hidden=true;updateCountdown();$('#countdown').focus();}
  else if(action==='exam-delete'){state.examDate='';save();$('#exam-editor').hidden=true;updateCountdown();$('#countdown').focus();}
  else if(action==='exam-close'){$('#exam-editor').hidden=true;$('#countdown').focus();}
  else if(action==='dismiss-award')$('#achievement').hidden=true;
  else if(action==='transcript'){const id=b.dataset.q,show=!shownTranscripts.has(id);if(show)shownTranscripts.add(id);else shownTranscripts.delete(id);$('#script-'+id).hidden=!show;b.setAttribute('aria-expanded',String(show));b.textContent=show?'会話の文字を閉じる':'会話の文字を見る';}
  else if(action==='voice-preview')speak('社員：間に合うように、資料を先に確認しておきます。\n先輩：ありがとうございます。間に合わない場合は、早めに連絡してください。',1,$('#voice-preview-status'));
  else if(action==='recall'){const entry=state.notebook[b.dataset.word],offset=Number(b.dataset.offset);if(entry&&reviewSchedule(entry).find(r=>r.offset===offset)?.due&&!Object.values(entry.recalled||{}).includes(japanDate())){entry.recalled||={};entry.recalled[offset]=japanDate();if(!state.known.includes(b.dataset.word))state.known.push(b.dataset.word);const watered=gardenReview();save();render();if(!watered)toast('見ずに思い出した記録を保存しました。');}}
  else if(action==='print-notebook')window.print();
});
document.addEventListener('change',e=>{
  if(e.target.matches('[data-written]')){const id=e.target.dataset.written;if(e.target.checked)state.notebook[id]||={writtenAt:japanDate(),recalled:{}};else delete state.notebook[id];save();const y=window.scrollY,shell=$('.main-shell'),sy=shell?.scrollTop||0;render();window.scrollTo(0,y);shell?.scrollTo?.(0,sy);}
  if(e.target.id==='notebook-day'){notebookDay=Number(e.target.value);$('#word-results').innerHTML=wordResults();}
  if(e.target.id==='print-day')location.hash='notebook/'+e.target.value;
  if(e.target.matches('[data-voice]')){state.voices[Number(e.target.dataset.voice)]=e.target.value;save();}
});
