document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='doc-answer'){documentAnswers[b.dataset.doc]=Number(b.dataset.choice);render();}if(b.dataset.action==='doc-retry'){delete documentAnswers[b.dataset.doc];render();}});


// Reading overrides affect synthesis only; the displayed source remains unchanged.
function speechText(text){return text.replace(/間に合/g,'まにあ').replace(/御社/g,'おんしゃ').replace(/弊社/g,'へいしゃ');}
function speechSegments(text){
 const speakers=new Map(),segments=[];
 for(const line of text.split(/\n+/).filter(Boolean)){
  const m=line.match(/^([^：:]{1,14})[：:](.*)$/),speaker=m?.[1]||'ナレーション';
  if(!speakers.has(speaker))speakers.set(speaker,speakers.size);
  const value=speechText(m?m[2]:line);
  // Preserve whole turns for prosody; split only unusually long turns at sentence boundaries.
  let chunk='';for(const sentence of value.match(/[^。！？]+[。！？]?/g)||[value]){if(chunk.length+sentence.length>220&&chunk){segments.push({text:chunk,speaker,index:speakers.get(speaker)});chunk='';}chunk+=sentence;}
  if(chunk)segments.push({text:chunk,speaker,index:speakers.get(speaker)});
 }
 return segments;
}
function selectedVoice(index,voices){
 const explicit=voices.find(v=>v.voiceURI===state.voices[index]);if(explicit)return explicit;
 if(index===0)return voices[0]; // Keep the previously working first speaker's automatic choice.
 return voices.find(v=>/Nanami.*(?:Online|Natural)|(?:Online|Natural).*Nanami/i.test(v.name))||voices.find(v=>/Nanami|Mayu|Ayumi|Haruka|Kyoko|O-Ren/i.test(v.name))||voices[index%voices.length];
}
let wordAudio=null,wordAudioId=null,wordAudioButton=null;
function resetWordAudio(){
 if(wordAudio){wordAudio.onplay=null;wordAudio.onended=null;wordAudio.onerror=null;wordAudio.pause();wordAudio.removeAttribute('src');wordAudio.load();wordAudio=null;}
 if(wordAudioButton){wordAudioButton.innerHTML=icon('sound')+' 聞く';wordAudioButton.setAttribute('aria-pressed','false');wordAudioButton=null;}
 wordAudioId=null;
}
function stopAudio(){
 voiceRun++;clearTimeout(voicePause);
 resetWordAudio();
 if('speechSynthesis'in window&&(speechSynthesis.speaking||speechSynthesis.pending))speechSynthesis.cancel();
 utterance=null;if(audioStatusEl){audioStatusEl.textContent='停止しました。';audioStatusEl=null;}
}
function playWordAudio(id,button){
 if(wordAudioId===id&&wordAudio){stopAudio();return;}
 stopAudio();const run=voiceRun,status=document.getElementById('word-audio-'+id),src=WORD_AUDIO[id];
 if(!src){if(status)status.textContent='この単語の音声が見つかりません。';return;}
 audioStatusEl=status;
 if(status)status.textContent='音声を準備しています…';
 const fail=()=>{if(run!==voiceRun)return;stopAudio();if(status)status.textContent='再生できませんでした。「聞く」をもう一度押してください。';};
 try{
  const player=new Audio(src);wordAudio=player;wordAudioId=id;wordAudioButton=button;
  player.preload='auto';player.playbackRate=1;player.setAttribute('playsinline','');
  button.textContent='■ 停止';button.setAttribute('aria-pressed','true');
  player.onplay=()=>{if(run===voiceRun&&status)status.textContent='再生中';};
  player.onended=()=>{if(run!==voiceRun)return;stopAudio();if(status)status.textContent='再生しました。';};
  player.onerror=fail;
  // Keep play() in the tap/click handler, including on iPhone. The file already uses speed 0.8.
  const started=player.play();if(started&&typeof started.catch==='function')started.catch(fail);
 }catch{fail();}
}
function speak(text,rate=1,status=null){
 stopAudio();const run=voiceRun;audioStatusEl=status;
 if(!('speechSynthesis'in window)||!('SpeechSynthesisUtterance'in window)){if(status)status.textContent='この端末では音声を使えません。会話の文字を確認してください。';return;}
 const segments=speechSegments(text);let position=0,attempts=0;const prepared=new Set();
 const failure=()=>{if(run!==voiceRun)return;if(status)status.textContent='音声を開始できませんでした。再生を押すか、会話の文字を確認してください。';utterance=null;};
 const play=()=>{
  if(run!==voiceRun)return;
  const voices=japaneseVoices();if(!voices.length){if(attempts++<12){voicePause=setTimeout(play,100);return;}failure();return;}
  if(position>=segments.length){if(status)status.textContent='最後まで再生しました。もう一度聞くこともできます。';utterance=null;audioStatusEl=null;return;}
  const part=segments[position],slot=part.index%2,voice=selectedVoice(slot,voices),key=voice.voiceURI||voice.name;
  const priming=!prepared.has(key),value=priming?'音声を準備します。':part.text;
  utterance=new SpeechSynthesisUtterance(value);utterance.lang='ja-JP';utterance.voice=voice;utterance.pitch=1;utterance.volume=priming?0:1;
  utterance.rate=priming?1:Math.max(.65,Math.min(1.3,rate*(state.voiceRates?.[slot]||1)));
  const current=utterance;
  current.onstart=()=>{if(run===voiceRun&&status)status.textContent=priming?'音声を準備しています…':`再生中 · ${part.speaker}`;};
  current.onend=()=>{if(run!==voiceRun)return;if(priming){prepared.add(key);voicePause=setTimeout(play,Math.max(300,state.audioLead||500));}else{position++;voicePause=setTimeout(play,segments[position]?.speaker===part.speaker?180:360);}};
  current.onerror=e=>{if(['canceled','interrupted'].includes(e.error)||run!==voiceRun)return;failure();};
  speechSynthesis.speak(current);
 };
 // A cancellation must settle before new speech is submitted. Keep every initial phoneme intact.
 if(status)status.textContent='音声を準備しています…';voicePause=setTimeout(play,180);
}
function voiceSettings(){return intro('LISTENING','音声の設定','例文・聴解・聴読解の声と速さを選び、文章の先頭から試し聞きできます。')+`<section class="panel"><p class="notice">単語帳の90語は、VOICEVOX:波音リツ（ノーマル・話速0.8）の音声です。ここで選ぶ声や速さは、例文・聴解・聴読解に適用されます。</p><p>発言を細かく切りすぎず、文のまとまりを保って読み上げます。声の切り替え前に準備を行い、本文の冒頭が欠けにくいよう待ち時間を設けています。</p><div id="voice-list">${voiceSelectors()}</div><div class="voice-selectors">${[0,1].map(i=>`<label>話者 ${i+1} の速さ <select data-voice-rate="${i}">${[.9,.96,1,1.04].map(v=>`<option value="${v}" ${state.voiceRates[i]===v?'selected':''}>${v===1?'標準':v<1?'ややゆっくり '+v:'やや速く '+v}</option>`).join('')}</select></label>`).join('')}<label>再生準備の待ち時間<select id="audio-lead">${[500,900,1400].map(v=>`<option value="${v}" ${state.audioLead===v?'selected':''}>${v===500?'標準':v===900?'長め':'さらに長め'}（${v/1000}秒）</option>`).join('')}</select></label></div><div class="actions"><button class="btn blue" data-action="voice-preview">両方の声を試す</button><button class="btn light" data-action="stop">停止</button></div><p id="voice-preview-status" role="status"></p><div class="notice">冒頭の欠けが残る端末では、待ち時間を「長め」にして試してください。女性の声は候補を切り替え、速さも比べられます。音声の品質は端末によって異なります。</div><p class="small">読み方の確認：「間に合う」「間に合えば」「間に合わない」は「まにあう」「まにあえば」「まにあわない」と読みます。</p></section>`;}
document.addEventListener('change',e=>{if(e.target.matches('[data-voice-rate]')){state.voiceRates[Number(e.target.dataset.voiceRate)]=Number(e.target.value);save();}if(e.target.id==='audio-lead'){state.audioLead=Number(e.target.value);save();}});

