function topicStudy(id){const t=LEARNING_TOPICS.find(t=>t.id===id);if(!t)return null;const a=topicAnswers[id];return `<a href="#study" class="back">← 学習・解説</a>`+intro('COMMUNICATE AT WORK',t.title,t.summary)+`<div class="topic-layout"><div><section class="panel"><h2>まず押さえる3つのこと</h2><ol>${t.points.map(p=>`<li>${txt(p)}</li>`).join('')}</ol></section><section class="panel section-space"><h2>会話で確認しよう</h2><div class="conversation">${t.examples.map(e=>`<p><b>${txt(e.speaker)}</b>${txt(e.text)}</p>`).join('')}</div></section><section class="panel section-space"><h2>確認問題</h2><p>${txt(t.check.prompt)}</p><div class="choices section-space">${t.check.options.map((o,i)=>`<button class="choice ${a!==undefined?(i===t.check.answer?'correct':i===a?'wrong':''):''}" data-action="topic-answer" data-topic="${id}" data-choice="${i}" ${a!==undefined?'disabled':''}><span class="letter">${i+1}</span><span>${txt(o)}</span></button>`).join('')}</div>${a!==undefined?`<div class="feedback ${a===t.check.answer?'':'bad'}"><b>${a===t.check.answer?'正解です。':'根拠を確認しましょう。'}</b><br>${txt(t.check.explain)}</div><button class="btn text" data-action="topic-retry" data-topic="${id}">もう一度考える</button>`:''}</section></div><aside><section class="panel"><h2>よくある間違いと比べる</h2><div class="compare-example"><b class="small">気を付けたい例</b><p>${txt(t.comparison.mistake)}</p></div><div class="compare-example good"><b class="small">場面に合う表現・対応</b><p>${txt(t.comparison.better)}</p></div><p>${txt(t.comparison.reason)}</p></section><section class="panel section-space"><h2>練習につなげよう</h2><div class="guide-links">${t.relatedDays.map(d=>`<a href="#lesson/${d}">DAY ${String(d).padStart(2,'0')} · ${esc(LESSONS[d-1].title)} →</a>`).join('')}</div><a href="#practice" class="btn soft">テストにもチャレンジ →</a></section></aside></div>`;}
function topicCards(){return `<h2 class="study-group-title">場面に合う伝え方・読み取り方</h2><p class="small muted">ポイント → 会話例 → 間違いとの比較 → 確認問題。言葉の形と、相手の意図を結び付けましょう。</p><div class="document-cards">${LEARNING_TOPICS.map((t,i)=>`<a class="document-card" href="#study/${t.id}"><span class="doc-number">0${i+1}</span><div><h2>${t.title}</h2><p>${t.summary}</p><span>解説と確認問題へ →</span></div></a>`).join('')}</div>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.topic;if(b.dataset.action==='topic-answer'){topicAnswers[id]=Number(b.dataset.choice);render();}if(b.dataset.action==='topic-retry'){delete topicAnswers[id];render();}});

// Growth is derived from completed lessons. Reopening a page never earns water.
const PLANTS=[{name:'デイジー',color:'#f3cf65'},{name:'チューリップ',color:'#df8290'},{name:'アネモネ',color:'#9a8ccb'},{name:'ポピー',color:'#e79369'},{name:'ブルースター',color:'#80b7da'}];
let gardenAnimation=null,gardenTimer=null;
function gardenState(){state.garden||={selected:1,reviews:{},reducedMotion:false};state.garden.reviews||={};return state.garden;}
function plantInfo(n){const g=gardenState(),days=unitDays(n),done=days.filter(d=>state.completed.includes(d)).length,reviews=Object.values(g.reviews).filter(v=>v===n).length,bloom=!!state.trophies['unit'+n],open=n===1||done>0||!!state.trophies['unit'+(n-1)];const stage=bloom?4:Math.min(3,Math.ceil((done+Math.min(reviews,2))/days.length*3));return {n,...PLANTS[n-1],done,total:days.length,reviews,bloom,open,stage,label:['たね','ふたば','葉が育った','つぼみ','開花！'][stage]};}
function flowerPixels(n){const color=PLANTS[n-1].color,shapes=[
 '<path d="M28 4h8v9h8v9h-8v9h-8v-9h-9v-9h9zM22 7h5v6h-5zM37 7h5v6h-5zM22 23h5v5h-5zM37 23h5v5h-5z" fill="#fffaf1"/><path d="M27 13h10v10H27z" fill="#e7ba4d"/>',
 `<path d="M21 9h5v5h3V9h6v5h3V9h5v16h-5v5H26v-5h-5z" fill="${color}"/><path d="M29 15h6v13h-6z" fill="#edacb4"/>`,
 `<path d="M26 5h12v6h7v13h-7v6H26v-6h-7V11h7z" fill="${color}"/><path d="M25 10h5v5h-5zM36 22h5v5h-5z" fill="#c0b5e4"/><path d="M28 14h9v9h-9z" fill="#5d587a"/>`,
 `<path d="M20 8h10v4h4V8h10v13h-5v9H25v-9h-5z" fill="${color}"/><path d="M23 10h7v9h-7z" fill="#f0b396"/><path d="M29 19h7v7h-7z" fill="#65554b"/>`,
 `<path d="M29 4h6v9h12v7h-8v5h4v6h-9v-7h-4v7h-9v-6h4v-5h-8v-7h12z" fill="${color}"/><path d="M29 15h6v7h-6z" fill="#f5df9a"/>`
 ];return shapes[n-1];}
function plantSVG(n,stage){const p=PLANTS[n-1],s=stage===undefined?plantInfo(n).stage:stage;return `<svg class="pixel-plant" viewBox="0 0 64 72" role="img" aria-label="${p.name}・${['たね','ふたば','葉が育った','つぼみ','開花'][s]}" shape-rendering="crispEdges"><ellipse cx="32" cy="67" rx="23" ry="3" fill="#dce5d1"/><g class="plant-growth">${s===0?'<path d="M29 47h6v4h-6z" fill="#9b6e44"/>':`<path d="M30 ${s===1?37:22}h4v30h-4z" fill="#497658"/><path d="M30 39H20v-4h-4v-7h8v4h6zM34 44h10v-4h5v-7H39v4h-5z" fill="#88ae6e"/>${s>=2?'<path d="M30 28h-9v-4h-4v-7h8v4h5zM34 33h9v-4h5v-7h-8v4h-6z" fill="#5e9368"/>':''}${s===3?`<path d="M28 15h8v13h-8zM25 19h14v6H25z" fill="${p.color}"/><path d="M28 25h8v5h-8z" fill="#497658"/>`:''}${s===4?flowerPixels(n):''}`}</g><path d="M16 49h32v7H16z" fill="#b87c60"/><path d="M20 56h24v9H20zM24 65h16v3H24z" fill="#cc9474"/><path d="M23 56h4v8h-4z" fill="#e2b293"/><path d="M18 49h28v3H18z" fill="#e1ac86"/></svg>`;}
function gardenWidget(){const g=gardenState(),p=plantInfo(g.selected),animation=gardenAnimation?.n===g.selected;return `<a class="garden-widget ${animation?'watering':''}" href="#garden" aria-label="わたしの庭を開く。${p.name}、${p.label}"><span class="pot-scene">${plantSVG(g.selected)}${animation?'<span class="watering-can" aria-hidden="true"><svg width="28" height="24" viewBox="0 0 28 24"><path d="M8 9h13v12H8zM8 13L2 8v5l6 7M21 10h5v8h-5" fill="#7ca8b9" stroke="#527a8c" stroke-width="2"/><path d="M12 8V4h6v4" fill="none" stroke="#527a8c" stroke-width="2"/></svg></span><span class="water-drops" aria-hidden="true">⋮ ⋮</span>':''}</span><span><b>わたしの庭</b><small>${animation?'水やり、ありがとう':p.label} ↗</small></span></a>`;}
function refreshGarden(){const host=$('#garden-dock');if(!host)return;document.body.classList.toggle('garden-still',gardenState().reducedMotion);host.hidden=location.hash.startsWith('#quiz')||location.hash.startsWith('#notebook');host.innerHTML=gardenWidget();}
function waterGarden(n,message){gardenState().selected=n;gardenAnimation={n};refreshGarden();clearTimeout(gardenTimer);gardenTimer=setTimeout(()=>{gardenAnimation=null;refreshGarden();},2800);toast(message);}
function gardenReview(){const g=gardenState(),today=japanDate();if(g.reviews[today])return false;let n=g.selected;if(!plantInfo(n).open||plantInfo(n).bloom)n=[1,2,3,4,5].find(i=>plantInfo(i).open&&!plantInfo(i).bloom)||1;g.reviews[today]=n;waterGarden(n,'復習できました。今日の水やりを記録しました！');return true;}
function garden(){const g=gardenState(),plants=[1,2,3,4,5].map(plantInfo);return intro('GROW WITH YOUR LEARNING','わたしの庭','小さな一歩を、ひとつずつ。あなたの学習で花が育ちます。')+`<div class="garden-summary"><div><b>${plants.filter(p=>p.bloom).length} / 5 種類が開花</b><p>休んだ日があっても、植物は枯れません。</p></div><label class="check-row"><input type="checkbox" id="garden-motion" ${g.reducedMotion?'checked':''}>動きを控えめにする</label></div><div class="garden-grid">${plants.map(p=>`<article class="garden-card ${p.open?'':'locked'} ${p.bloom?'bloomed':''}"><span class="pill">${p.n===5?'FINAL':'UNIT 0'+p.n}</span><div class="garden-pot">${plantSVG(p.n,p.open?p.stage:0)}</div><h2>${p.name}</h2><p class="plant-stage">${p.open?p.label:'これから育てる鉢'}</p><p class="small">レッスン ${p.done} / ${p.total} 完了<br>テスト ${state.passes['unit'+p.n]?'✓ 達成':'未達成'}${p.reviews?`<br>復習の水やり ${p.reviews}日`:''}</p><div class="progress"><span style="width:${p.done/p.total*100}%"></span></div>${p.open?`<button class="btn ${g.selected===p.n?'soft':'light'}" data-action="select-plant" data-plant="${p.n}" aria-pressed="${g.selected===p.n}">${g.selected===p.n?'✓ 右下に表示中':'右下に飾る'}</button>`:`<p class="small muted">この単元のレッスンを1つ終えるか、前の単元の花が咲くと育て始められます。</p>`}<a class="btn text" href="#lesson/${unitDays(p.n).find(d=>!state.completed.includes(d))||unitDays(p.n)[0]}">この単元の練習へ →</a></article>`).join('')}</div><section class="panel section-space"><h2>花が咲くまで</h2><ol class="garden-rules"><li>レッスンを初めて完了すると、その単元の鉢に水やり。たね → ふたば → 葉 → つぼみと育ちます。</li><li>間違えた問題を正解に直すか、単語帳の予定された復習を記録すると、1日1回、復習の水やり。右下の鉢を優先して育てます。</li><li>単元の全レッスンとテストの達成で、トロフィーと花を獲得。FINALは単元1〜4のトロフィーも集めると開花します。</li></ol><p class="small muted">同じ完了ボタンの連打やページの再表示では成長しません。復習だけでは開花せず、つぼみまで育ちます。これまでに完了したレッスンも成長に反映します。</p><div class="actions"><a class="btn blue" href="#plan">練習問題へ</a><a class="btn light" href="#practice">テストへ</a><a class="btn text" href="#home">トロフィーを見る →</a></div></section>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="select-plant"]');if(!b)return;const n=Number(b.dataset.plant);if(n>=1&&n<=5&&plantInfo(n).open){gardenState().selected=n;save();render();}});
document.addEventListener('change',e=>{if(e.target.id==='garden-motion'){gardenState().reducedMotion=e.target.checked;save();refreshGarden();}});

// Phase 3 adds fields to the existing record; contentVersion and storage keys stay intact.
const PHASE3_DATE='2026-11-18';
const phaseSchool=typeof boot!=='undefined';
let phaseReportQueue=[],phaseReportBusy=false,phaseReportTimer=null,phaseReportError='',phaseReportBlocked=false,phaseReportVolatile=false,phaseReportFocus=null;
const phaseReportKey=KEY+':reports';
const phaseCategories={content:'問題・答え・解説',audio:'音声・読み方',display:'画面・操作',other:'その他'};
const phaseRoutes=['home','plan','lesson','practice','quiz','question','words','notebook','review','study','garden','guide','voice-settings'];
let phaseReviewType='all';
function phaseState(){state.phase3||={};state.phase3.days||={};state.phase3.acks||={};if(!Number.isInteger(state.phase3.weekGoal)||state.phase3.weekGoal<1||state.phase3.weekGoal>7)state.phase3.weekGoal=3;return state.phase3;}
function phaseAck(id){return phaseSchool?!!state.schoolAcks?.[id]:!!phaseState().acks[id];}
function phaseDays(){return Object.keys(phaseSchool?(state.schoolDays||{}):phaseState().days).filter(d=>dateNumber(d)!==null&&d<=japanDate()).sort();}
function phaseMarkAnswer(){if(!phaseSchool)phaseState().days[japanDate()]=true;}
function phaseWeekStart(today=japanDate()){const w=new Date(today+'T00:00:00Z').getUTCDay();return calendarAfter(today,-((w+6)%7));}
function phaseCalendar(){
  const today=japanDate(),dates=phaseDays(),week=phaseWeekStart(today),goal=phaseState().weekGoal,weekly=dates.filter(d=>d>=week).length;
  const [y,m]=today.split('-').map(Number),first=today.slice(0,8)+'01',offset=(new Date(first+'T00:00:00Z').getUTCDay()+6)%7,n=new Date(Date.UTC(y,m,0)).getUTCDate();
  const cells=Array.from({length:offset},()=>'<span aria-hidden="true"></span>').concat(Array.from({length:n},(_,i)=>{const date=first.slice(0,8)+String(i+1).padStart(2,'0'),learned=dates.includes(date);return `<span class="calendar-day ${learned?'learned':''} ${date===today?'today':''}" ${date===today?'aria-current="date"':''} aria-label="${m}月${i+1}日${learned?'、回答した日':''}${date===today?'、今日':''}">${i+1}${learned?'<small aria-hidden="true">●</small>':''}</span>`;}));
  const last=dates.at(-1),gap=last?dateNumber(today)-dateNumber(last):0;
  return `<section class="panel phase-calendar"><div><span class="eyebrow">MY LEARNING</span><h2>学びを少しずつ積み重ねよう</h2><p>${gap>=3?'おかえりなさい。休んだ日があっても大丈夫。今日は2問から再開しましょう。':weekly>=goal?'今週の目標を達成しました。次は、迷った問題をもう一度。':'今日は2問に答え、解説を確認するところから。'}</p><div class="phase-counts"><p><b>${dates.length}</b> 日<br>累計学習日数</p><p><b>${weekly} / ${goal}</b> 日<br>今週の目標</p><p><b>${state.completed.length} / 30</b><br>必修の完了</p></div><label>週に学ぶ日数 <select id="phase-week-goal">${[1,2,3,4,5,6,7].map(n=>`<option value="${n}" ${goal===n?'selected':''}>${n}日</option>`).join('')}</select></label><p class="small muted">1問以上回答した日を数えます。同じ日に何問解いても1日です。${phaseSchool?'学校で受け付けた日本時間の日付を表示します。未送信分は受付後に反映されます。':'この端末で記録した日本時間の日付です。更新前の日付は推測して追加しません。'}週目標は自分用・この端末に保存します。</p></div><div><h3>${y}年${m}月</h3><div class="phase-calendar-grid">${['月','火','水','木','金','土','日'].map(s=>`<b>${s}</b>`).join('')}${cells.join('')}</div><p class="small muted">● 回答した日　囲み：今日</p></div></section>`;
}
function phaseLesson(day){
  if(!Number.isInteger(day)||day<1||day>30)return empty('練習問題が見つかりません','一覧から選んでください。','#plan','練習問題へ');
  const l=LESSONS[day-1],qs=QUESTIONS.filter(q=>q.day===day&&!q.optional),done=state.completed.includes(day);
  return `<a class="back" href="#plan">← 練習問題</a>`+intro(`DAY ${String(day).padStart(2,'0')} / 30`,l.title,txt(l.goal))+`<p class="phase-path">ポイント → 必修2問 → 解説を確認 → 完了 → 単語帳・テスト・復習</p><div class="lesson-layout"><div class="lesson-body"><section class="panel"><span class="pill">01 · ポイント</span><h2>場面と意味をつなげよう</h2><p>${txt(l.point)}</p><p class="phrase">${txt(l.phrase)}</p><button class="btn text" data-action="speak-phrase" data-day="${day}">${icon('sound')} 例文を聞く</button><span id="phrase-status" role="status"></span></section><section><h2>02 · 必修の2問</h2><p>まず自分で答え、解説と4つの選択肢の理由を読みましょう。音声の問題は、答えてからスクリプトも確認します。</p>${qs.map(q=>questionHTML(q,'daily')).join('')}</section><section class="panel phase-extra"><span class="pill">任意 · もっと練習</span><h2>追加5問は準備中</h2><p>先生が内容を確認してから公開します。今は必修2問で完了できます。公開後は、必修2問＋追加5問の計7問に取り組めます。</p><p class="small muted">2026年11月18日時点：追加問題は未公開です。</p></section><section class="panel"><span class="pill">任意 · 単語を自分のものに</span><h2>今日の3語をノートに書こう</h2><div class="vocab-mini">${l.words.map(w=>`<div><b>${txt(w[0])}</b><p>${txt(w[2])}</p></div>`).join('')}</div><a class="btn blue" href="#words/${day}">単語帳を開く →</a><p class="small muted">書いたらチェック。単語帳の「練習問題に戻る」で、このDAYに戻れます。ノートの記入は必修の完了条件ではありません。</p></section><section class="panel"><h2>自分の言葉で使ってみよう</h2><p>${txt(l.task)}</p><label for="lesson-note-${day}">今日分かったこと・次に気を付けること（任意）</label><textarea id="lesson-note-${day}" data-note="day-${day}" placeholder="例：『前に』は開始時刻より早い。">${esc(state.notes['day-'+day]||'')}</textarea><div class="actions"><a class="btn light" href="#practice">テストにチャレンジ</a><a class="btn light" href="#review">復習ノートへ</a></div></section></div><aside class="lesson-aside panel"><h3>03 · 今日の必修を完了</h3><p id="lesson-completion-info">${completionInfo(day)}</p><button class="btn full ${done?'soft':'blue'}" data-action="complete-day" data-day="${day}" ${canComplete(day)?'':'disabled'}>${done?'✓ この日は学習済み':'今日の学習を完了'}</button><p class="small">2問に答え、両方の「解説を確認した」を押すと完了できます。間違えても大丈夫。理由を読んでから次へ進みましょう。</p><a class="btn text full" href="#lesson/${day===30?1:day+1}">${day===30?'DAY 1を復習する':'次の練習問題へ'} →</a><a href="#guide" class="btn text">勉強の進め方を見る</a></aside></div>`;
}
function phaseGuide(){return intro('HOW TO LEARN','勉強の進め方','今日は2問から。分かったことを、少しずつ増やしましょう。')+`
<section class="panel"><h2>ページを移動しながら学ぶ</h2><ol class="phase-steps">
<li><b>練習問題</b><p>DAYを選び、ポイントを読んで2問に回答。解説を読んで「解説を確認した」を押し、「今日の学習を完了」を押します。</p><a href="#plan">練習問題を選ぶ →</a></li>
<li><b>単語帳</b><p>今日の3語の読み方・意味・例文を確認し、自分のノートに書きます。「ノートに書いた」にチェックしてから「練習問題に戻る」で元のDAYへ。書いた日から1日後・3日後・7日後を目安に、見ずに思い出す復習をしましょう。</p><a href="#words">単語帳を開く →</a></li>
<li><b>テスト</b><p>練習のあとにテストにチャレンジ！ 学習前や途中でも受けられます。最後に結果と解説を確認し、答えの根拠を自分の言葉で説明してみましょう。</p><a href="#practice">テストを選ぶ →</a></li>
<li><b>復習ノート</b><p>間違えた問題を選び、迷った理由をメモして解き直します。正解すると要復習一覧から外れます。ことばが原因なら単語帳へ、敬語や文書で迷ったら「学習・解説」へ戻りましょう。</p><a href="#review">復習ノートへ →</a> · <a href="#study">学習・解説へ →</a></li></ol><p>毎回、全ページを終える必要はありません。まずは必修2問と解説確認。余裕のある日に単語帳やテストへ進みましょう。</p></section>
<div class="guide-grid"><section class="panel"><h2>1問の中では、この順番</h2><ol><li>聴解はイラストがあれば確認し、文字を見ずに聞く。聴読解は図表を見ながら聞く。読解は文書を読む。</li><li>「だれが・何を・いつまでに」を手がかりに、選択肢を一つ選ぶ。</li><li>正解と解説を読み、「4つの選択肢の理由を比べる」を開く。</li><li>音声はスクリプトと照らし合わせて聞き直す。「解説を確認した」を押す。</li><li>迷ったところはメモし、必要なら「もう一度解く」で試す。</li></ol><p>単元テスト中はスクリプトを表示しません。終了後に確認できます。追加5問は準備中で、必修の完了には必要ありません。</p></section>
<section class="panel"><h2>🌱 植物は「続けた記録」</h2><p>DAYの必修を初めて完了すると、その単元の鉢に水がやられます。たね → ふたば → 葉 → つぼみと育ち、単元の全DAYを完了すると開花します。テストの点数は開花条件ではありません。</p><p>間違えた問題を解き直して正解した日や、単語帳の復習を記録した日にも、1日1回の水やりがあります。復習だけでは開花せず、つぼみまで育ちます。休んでも枯れません。</p><p>右下の鉢を押すと「わたしの庭」へ。5種類を並べて見たり、飾る鉢を選んだりできます。「動きを控えめにする」も選べます。スマホでは小さな鉢だけを表示します。</p><a href="#garden">わたしの庭へ →</a></section>
<section class="panel"><h2>🏆 トロフィーは「理解の達成」</h2><p>各単元と最後の確認テストで、12問中10問以上、かつ聴解・聴読解・読解の各4問中2問以上正解すると、そのテストのトロフィーを獲得します。レッスン完了前でも獲得できます。</p><p>再挑戦できます。以前のトロフィー・花は失いません。「単語帳のはじめの1語」「間違いを力に変えた」などの学習実績も残ります。</p><p>テストは同じ問題を繰り返すため、答えを覚えただけでないか、理由も確かめましょう。トロフィーや正答率はBJTの点数・レベルの認定ではありません。</p><a href="#home">達成状況を見る →</a></section>
<section class="panel"><h2>困ったとき・記録について</h2><p>各ページの「問題を報告する」から、問題や音声、画面の不具合を知らせられます。問題の下のボタンを使うと問題番号が自動で入ります。報告しても点数は変わりません。</p><p>${phaseSchool?'学校版の報告は先生の管理表へ送ります。通信できないときは端末に残し、再送します。「受付済み」の表示を確認してください。':'この公開HTML版からは学校へ直接送信しません。報告文を保存し、先生に渡してください。'}</p><p>${phaseSchool?'回答と完了の記録は学校へ送ります。単語帳・メモ・表示設定・自分の週目標は、この端末だけに保存されます。':'学習記録はこのブラウザー内に保存されます。別端末とは同期しません。'} 学校への送信待ちがあるときは、サイトのデータを削除しないでください。</p><button class="btn light" data-action="export">学習記録を保存（JSON）</button></section>
<section class="panel"><h2>この教材の目標</h2><p>JLPT N3程度の日本語を、仕事の場面で使う練習です。30DAYは学習内容の区切りで、毎日連続で進める必要はありません。1か月でのJ2到達には個人差があります。</p><p>独自の非公式教材です。「はじめのチェック」「総合練習」は練習問題を再利用し、単元テストは別問題です。公式サンプルでも初めての問題に触れましょう。</p><p>単語音声はVOICEVOX:波音リツ。会話・例文の音声は教材の設定に応じて再生します。<a href="#voice-settings">音声設定</a>も確認できます。</p></section></div>`+officialLinks();}
function phaseReportButton(q){return `<button type="button" class="btn text phase-report-button" data-phase-report="${esc(q?.id||'')}">問題を報告する${q?'（'+esc(q.id)+'）':''}</button>`;}
function phaseReportStore(){try{localStorage.setItem(phaseReportKey,JSON.stringify(phaseReportQueue));phaseReportVolatile=false;}catch{phaseReportVolatile=true;phaseReportError='端末に保存できません。画面を閉じずに、報告文を保存して先生に渡してください。';}phaseReportStatus();}
function phaseReportStatus(){
  const message=phaseReportError||(phaseReportBusy?'報告を送っています…':phaseReportQueue.length?`報告 ${phaseReportQueue.length}件が送信待ちです。通信が戻ったら再送します。`:'送信待ちの報告はありません。');
  document.querySelectorAll('[data-report-status]').forEach(el=>el.textContent=message);
}
function phaseReportSend(){
  clearTimeout(phaseReportTimer);if(!phaseSchool||phaseReportBusy||phaseReportBlocked||!phaseReportQueue.length)return phaseReportStatus();
  if(!navigator.onLine){phaseReportTimer=setTimeout(phaseReportSend,15000);return phaseReportStatus();}
  if(schoolBlocked){phaseReportError='学習記録の接続を確認してから報告を送ります。先生に相談してください。';return phaseReportStatus();}
  phaseReportBusy=true;phaseReportError='';phaseReportStatus();const report=phaseReportQueue[0];let settled=false;
  const timeout=setTimeout(()=>finish({ok:false,retryable:true,message:'受付の確認が取れていません。同じ報告番号で再送します。'}),30000);
  function finish(r){if(settled)return;settled=true;clearTimeout(timeout);phaseReportBusy=false;
    if(r?.ok&&r.reportId===report.reportId){phaseReportQueue=phaseReportQueue.filter(x=>x.reportId!==report.reportId);phaseReportStore();const status=document.getElementById('phase-report-result');if(status)status.textContent='先生への報告が受付済みになりました。ありがとうございます。';phaseReportTimer=setTimeout(phaseReportSend,400);}
    else{phaseReportError=r?.message||'報告を送信できません。端末に残して再送します。';if(r?.retryable===false)phaseReportBlocked=true;else phaseReportTimer=setTimeout(phaseReportSend,30000);}
    phaseReportStatus();
  }
  google.script.run.withSuccessHandler(finish).withFailureHandler(()=>finish({ok:false,retryable:true})).submitProblemReport({report});
}
function phaseDownloadText(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function phaseReportOpen(id=''){
  const old=document.getElementById('phase-report-dialog');if(old)old.remove();phaseReportFocus=document.activeElement;
  const route=location.hash.replace(/^#/,'').split('/'),page=phaseRoutes.includes(route[0])?route[0]:'home';
  const q=getQ(id)||(page==='question'?getQ(route[1]):page==='quiz'&&activeQuiz&&!activeQuiz.finished?getQ(activeQuiz.ids[activeQuiz.index]):null);
  const day=page==='lesson'?Number(route[1]):q?.day||0;
  const dialog=document.createElement('dialog');dialog.id='phase-report-dialog';dialog.setAttribute('aria-labelledby','phase-report-title');dialog.dataset.page=page;dialog.dataset.day=day>=1&&day<=30?day:0;
  dialog.innerHTML=`<form id="phase-report-form"><div class="section-heading"><h2 id="phase-report-title">問題を報告する</h2><button class="btn light" type="button" data-report-close aria-label="報告画面を閉じる">閉じる</button></div><p>気づいた点を教えてください。点数や学習記録は変わりません。</p><label for="phase-report-q">問題番号</label><select id="phase-report-q"><option value="">ページ全体について</option>${[...QUESTIONS,...ASSESSMENTS].map(x=>`<option value="${x.id}" ${q?.id===x.id?'selected':''}>${x.id} · ${CATS[x.type]}</option>`).join('')}</select><label for="phase-report-category">何についてですか</label><select id="phase-report-category">${Object.entries(phaseCategories).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><label for="phase-report-message">気づいたこと（1,000文字まで）</label><textarea id="phase-report-message" required maxlength="1000" placeholder="例：この言葉の読み方が違うと思います。"></textarea><p class="small muted">氏名・メールアドレスなどの個人情報は書かないでください。${phaseSchool?'先生には学校の学生IDと報告内容が届きます。':'このHTML版は直接送信できません。保存した報告文を先生に渡してください。'}</p><div class="actions"><button class="btn blue" type="submit">${phaseSchool?'先生へ送信':'報告文を保存'}</button><button class="btn light" type="button" id="phase-report-copy">報告文を保存</button></div><p id="phase-report-result" role="status" aria-live="polite"></p>${phaseSchool?'<p data-report-status role="status"></p><div class="actions"><button type="button" class="btn light" id="phase-report-retry">未送信の報告を再送</button><button type="button" class="btn light" id="phase-report-backup">未送信の報告を保存</button></div>':''}</form>`;
  document.body.append(dialog);dialog.addEventListener('close',()=>phaseReportFocus?.isConnected&&phaseReportFocus.focus());dialog.querySelector('[data-report-close]').onclick=()=>dialog.close();
  const fields=()=>({questionId:$('#phase-report-q').value,category:$('#phase-report-category').value,message:$('#phase-report-message').value.trim(),page,day:Number(dialog.dataset.day)});
  const text=r=>`BJT STEP 30 問題報告\n問題番号：${r.questionId||'ページ全体'}\nページ：${r.page}${r.day?' / DAY '+r.day:''}\n種類：${phaseCategories[r.category]}\n\n${r.message}\n`;
  $('#phase-report-copy').onclick=()=>phaseDownloadText(text(fields()),'BJT_問題報告.txt');
  $('#phase-report-retry')?.addEventListener('click',()=>{if(phaseReportBlocked){$('#phase-report-result').textContent='報告文を保存し、先生に相談してください。';return;}phaseReportSend();});
  $('#phase-report-backup')?.addEventListener('click',()=>phaseDownloadText(phaseReportQueue.map(r=>`報告番号：${r.reportId}\n`+text(r)).join('\n---\n'),'BJT_未送信の問題報告.txt'));
  $('#phase-report-form').onsubmit=e=>{e.preventDefault();const r=fields();if(!r.message)return;
    if(!phaseSchool){phaseDownloadText(text(r),'BJT_問題報告.txt');$('#phase-report-result').textContent='報告文を保存しました。先生に渡してください。学校への送信は行っていません。';return;}
    if(phaseReportBlocked||schoolBlocked||phaseReportQueue.length>=100){$('#phase-report-result').textContent='送信を確認する必要があります。報告文を保存し、先生に渡してください。';return;}
    phaseReportQueue.push({reportId:crypto.randomUUID(),studentBinding:boot.studentId,materialVersion:boot.materialVersion,occurredAt:new Date().toISOString(),...r});phaseReportStore();$('#phase-report-result').textContent=phaseReportVolatile?phaseReportError:'報告を端末に保存しました。受付の確認を待っています。';dialog.querySelector('[type="submit"]').disabled=true;phaseReportSend();
  };
  phaseReportStatus();dialog.showModal();$('#phase-report-message').focus();
}
function phase3Install(){
  phaseState();
  // Freeze legacy blooms before changing trophy rules. Never manufacture dates for past study.
  if(!state.phase3.initialized){state.phase3.legacyBlooms=[1,2,3,4,5].filter(n=>state.trophies['unit'+n]);state.phase3.initialized=PHASE3_DATE;}
  if(phaseSchool)state.schoolDays={...(state.schoolDays||{}),...(boot.progress.days||{})};
  canComplete=day=>QUESTIONS.filter(q=>q.day===day).length===2&&QUESTIONS.filter(q=>q.day===day).every(q=>state.answers[q.id]?.choice>=0&&phaseAck(q.id));
  completionInfo=day=>{const qs=QUESTIONS.filter(q=>q.day===day);return `必修 ${qs.filter(q=>state.answers[q.id]?.choice>=0).length}/2問 回答済み · 解説 ${qs.filter(q=>phaseAck(q.id)).length}/2問 確認済み。`;};
  const originalRecord=record;record=function(q,choice){originalRecord(q,choice);if(choice>=0)phaseMarkAnswer();};
  const originalExplanation=explanationHTML;explanationHTML=function(q){return originalExplanation(q)+(!phaseSchool&&state.answers[q.id]?.choice>=0?`<div class="school-ack"><button class="btn soft" data-phase-ack="${q.id}" ${phaseAck(q.id)?'disabled':''}>${phaseAck(q.id)?'✓ 解説を確認済み':'解説を確認した'}</button></div>`:'')+phaseReportButton(q);};
  const originalQuestion=questionHTML;questionHTML=function(q,mode='daily'){const html=originalQuestion(q,mode);return (mode==='quiz'||mode==='retry'||!state.answers[q.id])?html.replace(/<\/article>$/,()=>phaseReportButton(q)+'</article>'):html;};
  lesson=phaseLesson;guide=phaseGuide;
  const originalPlan=plan;plan=function(){return originalPlan().replaceAll('＋ 読解 · ノート3語','＋ 読解 · 必修2問').replace('各単元の練習が終わったら','学習前や途中でも');};
  const originalNotebookReturn=notebookReturn;notebookReturn=function(){return originalNotebookReturn().replace('3語を書きました。次は問題に挑戦！','3語を書きました。元の練習ページに戻れます。');};
  const originalUnlock=unlockTrophies;unlockTrophies=function(){
    // Retain the original supplementary achievements, but use test mastery for unit trophies.
    for(let n=1;n<=5;n++)if(state.passes['unit'+n]&&!state.trophies['unit'+n]){state.trophies['unit'+n]=state.passes['unit'+n];const el=$('#achievement');if(el){el.innerHTML=`<span class="award-icon">🏆</span><div><small>テスト達成</small><b>${n===5?'最後の確認テスト':'単元 '+n}のトロフィー</b></div><button data-action="dismiss-award" aria-label="実績のお知らせを閉じる">×</button>`;el.hidden=false;}}
    originalUnlock();
  };
  const originalTrophy=trophyHTML;trophyHTML=n=>originalTrophy(n).replace('レッスン完了 ＋ テスト達成','テストの達成条件を満たす').replace('30日チャレンジ達成','最後の確認テスト達成');
  const originalUnitCard=unitCard;unitCard=n=>originalUnitCard(n).replace('トロフィー獲得！ 庭に花が咲きました。','テスト達成のトロフィー獲得！').replace(' 最後のトロフィーには単元1〜4のトロフィーも必要です。','');
  plantInfo=function(n){const g=gardenState(),days=unitDays(n),done=days.filter(d=>state.completed.includes(d)).length,reviews=Object.values(g.reviews).filter(v=>v===n).length,bloom=done===days.length||state.phase3.legacyBlooms.includes(n),open=n===1||done>0||bloom||unitDays(n-1).every(d=>state.completed.includes(d))||state.phase3.legacyBlooms.includes(n-1),stage=bloom?4:Math.min(3,Math.ceil((done+Math.min(reviews,2))/days.length*3));return {n,...PLANTS[n-1],done,total:days.length,reviews,bloom,open,stage,label:['たね','ふたば','葉が育った','つぼみ','開花！'][stage]};};
  const originalGarden=garden;garden=()=>originalGarden().replace('単元の全レッスンとテストの達成で、トロフィーと花を獲得。FINALは単元1〜4のトロフィーも集めると開花します。','単元の全DAYの必修を完了すると開花します。テストは花の条件ではなく、理解を確かめるトロフィーの条件です。以前に咲いた花も残ります。');
  home=function(){const day=nextDay();return intro('YOUR JAPANESE, ONE STEP FORWARD','こんにちは。今日も、一歩ずつ。','N3の日本語を、仕事で使える力へ。')+`<section class="hero"><div class="hero-copy"><div class="tag">BJT STEP 30</div><h2>今日の2問から、<br>仕事の日本語へ。</h2><p>聞いて、読んで、理由を確かめる。<br>自分のペースで進めましょう。</p><div class="actions"><a class="btn blue" href="#lesson/${day}">DAY ${String(day).padStart(2,'0')} を開く →</a><a class="btn light" href="#guide">勉強の進め方</a></div></div>${art()}</section>`+phaseCalendar()+`<section class="panel"><h2>練習 → 単語帳 → テスト → 復習</h2><p>まず必修2問と解説を確認。単語をノートに書いたら、テストで理解を確かめ、迷った問題を復習しましょう。テストはいつでも受けられます。</p><div class="actions"><a class="btn light" href="#words/${day}">今日の単語帳</a><a class="btn light" href="#practice">テスト</a><a class="btn light" href="#review">復習 ${wrongIds().length}問</a><a class="btn text" href="#garden">わたしの庭</a></div></section>`+journey()+officialLinks()+legacyHTML();};
  const originalReview=review;review=()=>{const pending=QUESTIONS.filter(q=>state.answers[q.id]?.choice>=0&&!phaseAck(q.id));return `<section class="panel"><h2>復習は「理由を確かめて、もう一度」</h2><p>間違えた問題 → 原因をメモ → 解説・単語帳で確認 → 解き直す。正解すると下の要復習一覧から外れます。</p><div class="actions"><a class="btn light" href="#words">単語の復習へ</a><a class="btn light" href="#study">敬語・文書などを確認</a></div>${pending.length?`<details class="phase-pending"><summary>回答済みで、解説の確認がまだの練習問題：${pending.length}問</summary>${pending.map(q=>`<a class="btn text" href="#question/${q.id}">DAY ${q.day} · ${CATS[q.type]} · ${q.id} →</a>`).join('')}</details>`:''}<label for="phase-review-type">間違えた問題を分野で絞る</label> <select id="phase-review-type">${Object.entries({all:'すべて',...CATS}).map(([id,name])=>`<option value="${id}" ${phaseReviewType===id?'selected':''}>${name}（${wrongIds().filter(q=>id==='all'||getQ(q).type===id).length}問）</option>`).join('')}</select></section>`+originalReview();};
  const originalFooter=footer;footer=()=>originalFooter().replace('記録はこのブラウザーに保存',phaseSchool?'回答記録は学校へ送信':'記録はこのブラウザーに保存')+`<div class="phase-report-footer">${phaseReportButton()}${phaseSchool?'<small data-report-status aria-live="polite"></small>':''}</div>`;
  const originalRender=render;render=function(focus=false){originalRender(focus);if(location.hash==='#review')document.querySelectorAll('.review-item').forEach(el=>{const id=el.querySelector('[data-action="review-retry"]')?.dataset.q;if(id)el.hidden=phaseReviewType!=='all'&&getQ(id).type!==phaseReviewType;});phaseReportStatus();};
  try{const saved=JSON.parse(localStorage.getItem(phaseReportKey)||'[]');if(!Array.isArray(saved)||saved.length>100||saved.some(r=>!r.reportId||(phaseSchool&&r.studentBinding!==boot.studentId)))throw Error('QUEUE');phaseReportQueue=saved;}catch{phaseReportBlocked=true;phaseReportError='未送信の報告を読み込めません。端末のデータを消さず先生に相談してください。';}
  document.addEventListener('click',e=>{const report=e.target.closest('[data-phase-report]');if(report){phaseReportOpen(report.dataset.phaseReport);return;}const ack=e.target.closest('[data-phase-ack]');if(ack&&!ack.disabled){const id=ack.dataset.phaseAck,q=getQ(id);if(q&&state.answers[id]?.choice>=0){phaseState().acks[id]=new Date().toISOString();save();ack.disabled=true;ack.textContent='✓ 解説を確認済み';updateLessonCompletion(q.day);}}});
  document.addEventListener('change',e=>{if(e.target.id==='phase-week-goal'){phaseState().weekGoal=Number(e.target.value);save();render();}if(e.target.id==='phase-review-type'){phaseReviewType=e.target.value;render();}});
  window.addEventListener('online',phaseReportSend);
  window.addEventListener('beforeunload',e=>{if(phaseReportVolatile&&phaseReportQueue.length){e.preventDefault();e.returnValue='';}});
  document.querySelectorAll('a[href="#guide"]').forEach(a=>{if(a.textContent.includes('学習ガイド'))a.innerHTML=a.innerHTML.replace('学習ガイド','勉強の進め方');});
  save();setTimeout(phaseReportSend,1000);
}

